        #region Static Data - used

        public async Task<List<IpList>> GetAgentIps(int AgentId, string TenantId)

        {

            try

            {

                DataSet ds = new DataSet();

                string keydata = "WhiteListAgentIps_" + Convert.ToString(AgentId);


                if (!_cache.TryGetValue(keydata, out ds))

                {

                    SqlParameter[] para = new SqlParameter[] {

            new SqlParameter("@agentid",AgentId),

            new SqlParameter("@TenantId",TenantId),

            new SqlParameter("@IsSearch",1),

            new SqlParameter("@IsLive",Convert.ToInt32(_keySettings.IsLive))

        };

                    ds = await _dlConnection.GetDataSet_Limit("GetWhiteListIP", para, 2);

                    if (ds.Tables[0].Rows.Count > 0)

                    {

                        // Set cache with expiration (example: 12 hours)

                        var cacheEntryOptions = new MemoryCacheEntryOptions()

                            .SetAbsoluteExpiration(DateTime.Now.AddHours(1));  // Set cache to expire in 12 hours

                        _cache.Set(keydata, ds, cacheEntryOptions);

                    }

                }

                //string json = JsonConvert.SerializeObject(ds);

                //ds = JsonConvert.DeserializeObject<DataSet>(json);

                List<IpList> lst = HtmlExtensions.ToList<IpList>(ds.Tables[0]);

                return lst;

            }

            catch (Exception ex)

            {

                await _exception.Error(ex);

                return null;

            }

        }

        public async Task<List<Countries>> GetCountries()
        {
            try
            {
                DataTable dtCountries = await _dlConnection.GetDataTableAsync("GetAllCountry_Xconnect");
                dtCountries.Columns["Id"].ColumnName = "CountryId";
                dtCountries.Columns["GroupValue"].ColumnName = "Name";
                return HtmlExtensions.ToList<Countries>(dtCountries);
            }
            catch (Exception ex)
            {
                await _exception.Error(ex);
                return null;
            }
        }

        public async Task<List<CitiesData>> GetCityRecord(int countryid)
        {
            try
            {

                SqlParameter[] para = new SqlParameter[] {
                new SqlParameter("@CountryId",countryid),
                };
                DataTable dt = await _dlConnection.GetDataTableAsync("GetCityRecordCountryWise_Xconnect", para);
                dt.Columns["Id"].ColumnName = "CityId";
                dt.Columns["city"].ColumnName = "Name";
                List<CitiesData> lst = HtmlExtensions.ToList<CitiesData>(dt);
                return lst;
            }
            catch (Exception ex)
            {
                _ = _exception.Error(ex);
                return null;
            }
        }

        public XConnect.Models._Error GetErrorMsg(string type, string code, string description)
        {
            XConnect.Models._Error error = new XConnect.Models._Error();
            try
            {
                error.type = type;
                error.code = code;
                error.description = description;
            }
            catch (Exception ex)
            {
                _exception.Error(ex);
            }
            return error;
        }

        public async Task<bool> HotelIdRestriction(int AgentID, int HotelId)
        {
            try
            {
                string keydata = "HotelIDCache_" + Convert.ToString(AgentID);
                DataTable dt = new DataTable();
                if (!_cache.TryGetValue(keydata, out dt))
                {

                    SqlParameter[] para = new SqlParameter[] { new SqlParameter("@agentid", AgentID) };
                    dt = await _dlConnection.GetDataTable_Time("Xconnect_HotelIdRestriction", para, 2);
                    if (dt != null)
                    {
                        var cacheEntryOptions = new MemoryCacheEntryOptions()
                           .SetAbsoluteExpiration(DateTime.Now.AddHours(12));  // Set cache to expire in 12 hours

                        _cache.Set(keydata, dt, cacheEntryOptions);
                    }
                    else
                        return true;
                }

                DataRow[] drHotelIds = dt.Select("HotelId='" + HotelId + "'");
                if (drHotelIds.Length == 0)
                {
                    return true;
                }
                else
                {
                    return false;
                }
            }
            catch (Exception ex)
            {
                await _exception.Error(ex);
                return true;
            }
        }

