        public static int ChildAgeGrouping(int Age)
        {
            switch (Age)
            {
                case 1:
                case 2:
                    Age = 1;
                    break;
                case 3:
                case 4:
                case 5:
                    Age = 4;
                    break;
                case 6:
                case 7:
                case 8:
                case 9:
                case 10:
                case 11:
                case 12:
                    Age = 8;
                    break;
                default:
                    Age = 0;
                    break;
            }
            return Age;
        }
        void MergeDataSet(DataSet target, DataSet source)
        {
            try
            {


                if (source == null || source.Tables.Count == 0)
                    return;

                foreach (DataTable sourceTable in source.Tables)
                {
                    // Check if target already has this table
                    if (!target.Tables.Contains(sourceTable.TableName))
                    {
                        // Clone schema + add data
                        target.Tables.Add(sourceTable.Copy());
                    }
                    else
                    {
                        DataTable targetTable = target.Tables[sourceTable.TableName];

                        // If schemas are different, align them
                        foreach (DataColumn col in sourceTable.Columns)
                        {
                            if (!targetTable.Columns.Contains(col.ColumnName))
                            {
                                targetTable.Columns.Add(col.ColumnName, col.DataType);
                            }
                        }

                        // Import rows
                        foreach (DataRow row in sourceTable.Rows)
                        {
                            targetTable.ImportRow(row);
                        }
                    }
                }
            }
            catch (Exception x)
            {

            }
        }

        void MergeDataSet_old1(DataSet target, DataSet source)
        {
            try
            {


                // 🔑 Remove RoomRateSlabId column if exists in source
                foreach (DataTable table in source.Tables)
                {
                    if (table.Columns.Contains("RoomRateSlabId"))
                        table.Columns.Remove("RoomRateSlabId");
                    if (table.Columns.Contains("Recommended"))
                        table.Columns.Remove("Recommended");
                }

                // 🔑 Remove RoomRateSlabId column if exists in target
                foreach (DataTable table in target.Tables)
                {
                    if (table.Columns.Contains("RoomRateSlabId"))
                        table.Columns.Remove("RoomRateSlabId");
                    if (table.Columns.Contains("Recommended"))
                        table.Columns.Remove("Recommended");
                }

                if (target.Tables.Count == 0)
                {
                    foreach (DataTable table in source.Tables)
                    {
                        target.Tables.Add(table.Copy());
                    }
                }
                else
                {
                    for (int i = 0; i < source.Tables.Count; i++)
                    {
                        target.Tables[i].Merge(source.Tables[i], false, MissingSchemaAction.Add);
                    }
                }
            }
            catch (Exception x)
            {
            }
        }

