        void MergeDataSet_test(DataSet target, DataSet source)
        {
            // Normalize RoomRateSlabId in both target and source if "Rates" exists
            FixRoomRateSlabIdColumn(target);
            FixRoomRateSlabIdColumn(source);

            if (target.Tables.Count == 0)
            {
                foreach (DataTable table in source.Tables)
                {
                    target.Tables.Add(table.Copy());
                }
            }
            else
            {
                for (int i = 0; i < source.Tables.Count; i++)
                {
                    target.Tables[i].Merge(source.Tables[i], false, MissingSchemaAction.Add);
                }
            }
        }

        void FixRoomRateSlabIdColumn(DataSet ds)
        {
            if (ds.Tables.Contains("Rates"))
            {
                DataTable ratesTable = ds.Tables["Rates"];
                if (ratesTable.Columns.Contains("RoomRateSlabId") &&
                    ratesTable.Columns["RoomRateSlabId"].DataType != typeof(int))
                {
                    // Create new column with correct type
                    ratesTable.Columns.Add("RoomRateSlabId_Int", typeof(int));

                    foreach (DataRow row in ratesTable.Rows)
                    {
                        if (row["RoomRateSlabId"] != DBNull.Value)
                        {
                            row["RoomRateSlabId_Int"] = Convert.ToInt32(row["RoomRateSlabId"]);
                        }
                    }

                    // Drop old column and rename new one
                    ratesTable.Columns.Remove("RoomRateSlabId");
                    ratesTable.Columns["RoomRateSlabId_Int"].ColumnName = "RoomRateSlabId";
                }
            }
        }

        void MergeDataSeXXXXX(DataSet target, DataSet source)
        {
            // Fix for RoomRateSlabId column in "Rates" table
            if (source.Tables.Contains("Rates"))
            {
                DataTable ratesTable = source.Tables["Rates"];
                if (ratesTable.Columns.Contains("RoomRateSlabId") &&
                    ratesTable.Columns["RoomRateSlabId"].DataType != typeof(int))
                {
                    // Create a new column with correct type
                    ratesTable.Columns.Add("RoomRateSlabId_Int", typeof(int));

                    foreach (DataRow row in ratesTable.Rows)
                    {
                        if (row["RoomRateSlabId"] != DBNull.Value)
                        {
                            // Convert safely
                            row["RoomRateSlabId_Int"] = Convert.ToInt32(row["RoomRateSlabId"]);
                        }
                    }

                    // Remove old column and rename new one
                    ratesTable.Columns.Remove("RoomRateSlabId");
                    ratesTable.Columns["RoomRateSlabId_Int"].ColumnName = "RoomRateSlabId";
                }
            }

            // Proceed with merge
            if (target.Tables.Count == 0)
            {
                foreach (DataTable table in source.Tables)
                {
                    target.Tables.Add(table.Copy());
                }
            }
            else
            {
                for (int i = 0; i < source.Tables.Count; i++)
                {
                    target.Tables[i].Merge(source.Tables[i], false, MissingSchemaAction.Add);
                }
            }
        }
        public string CreateRadisCacheKey(string HotelId, HotelSearchParameter SearchPara, DataSet dsGetRediscacheConfig)//Added on 27-MAY-2025
        {
            try
            {
                StringBuilder RoomDataKeyBuilder = new StringBuilder();
                for (int r = 0; r < SearchPara.Rooms.Count; r++)
                {
                    int roomNumber = r + 1;
                    var room = SearchPara.Rooms[r];

                    RoomDataKeyBuilder.Append($"R{roomNumber}A={room.NoofAdults}+");
                    RoomDataKeyBuilder.Append($"R{roomNumber}C1A={ChildAgeGrouping(room.Child1Age)}+");
                    RoomDataKeyBuilder.Append($"R{roomNumber}C2A={ChildAgeGrouping(room.Child2Age)}+");
                }
                // Remove trailing '+'
                if (RoomDataKeyBuilder.Length > 0)
                {
                    RoomDataKeyBuilder.Length--; // remove last '+'
                }
                //DataRow[] DrNationality = dsGetRediscacheConfig.Tables[1].Select("GroupValue="+ SearchPara.Nationality + "");
                var DrNationality = dsGetRediscacheConfig.Tables[1]
                                    .AsEnumerable()
                                    .Where(row => string.Equals(
                                        row.Field<string>("GroupValue"),
                                        SearchPara.Nationality,
                                        StringComparison.OrdinalIgnoreCase))
                                        .ToArray();

                string Nationality = SearchPara.Nationality;
                if (DrNationality != null && DrNationality.Length > 0)
                {
                    Nationality = Convert.ToString(DrNationality[0]["LeadNationality"]);
                }

                string RoomDataKey = RoomDataKeyBuilder.ToString();

                DateTime CIN = DateTime.ParseExact(SearchPara.CheckInDate, "dd/MM/yyyy", CultureInfo.InvariantCulture);
                DateTime COUT = DateTime.ParseExact(SearchPara.CheckOutDate, "dd/MM/yyyy", CultureInfo.InvariantCulture);

                string CheckIN = CIN.ToString("MM-dd-yyyy");
                string CheckOUT = COUT.ToString("MM-dd-yyyy");

                string CacheKey = "OTH_Hid#" + HotelId + "_CI#" + CheckIN + "_CO#" + CheckOUT + "_NN#" + SearchPara.NoofNights + "_RD#" + RoomDataKey + "_NA#" + Nationality + "";
                return CacheKey;
            }
            catch (Exception x)
            {
                _exception.Error(x);
                return "";
            }
        }
        public async Task<DataSet> GetRediscacheConfig_DataSet(string SearchKey, int AgentId)
        {
            DataSet tokenDataSet = new DataSet();
            try
            {
                string keydata = "GetRediscacheConfig" + "_" + Convert.ToString(AgentId);

                if (!_cache.TryGetValue(keydata, out tokenDataSet))
                {
                    SqlParameter[] para = new SqlParameter[] {
new SqlParameter("@AgentId", AgentId),
};
                    tokenDataSet = await _dlConnection.GetDataSetAsync_DataReader("GetRedisCacheRule_Xconnect_API", para);

                    var cacheEntryOptions = new MemoryCacheEntryOptions()
                        //.SetAbsoluteExpiration(DateTime.Now.AddMinutes(5));  // Set cache to expire in 5 minutes
                        .SetAbsoluteExpiration(DateTime.Now.AddMinutes(60));  // Set cache to expire in 60 minutes Update on 1-DEC-2025

                    _cache.Set(keydata, tokenDataSet, cacheEntryOptions);
                }

                return tokenDataSet;
            }
            catch (Exception ex)
            {
                await _exception.Error(ex, SearchKey);
                return null;
            }
        }

