        public List<StarRating> GetStarRatingStringList(HotelSearchParameter SearchPara)
        {
            List<StarRating> rating = new List<StarRating>(); ;

            try
            {
                if (SearchPara.StarStart <= 1 && SearchPara.StarEnd >= 1)
                    rating.Add(new StarRating { Star = 1 });
                if (SearchPara.StarStart <= 2 && SearchPara.StarEnd >= 2)
                    rating.Add(new StarRating { Star = 2 });

                if (SearchPara.StarStart <= 3 && SearchPara.StarEnd >= 3)
                    rating.Add(new StarRating { Star = 3 });

                if (SearchPara.StarStart <= 4 && SearchPara.StarEnd >= 4)
                    rating.Add(new StarRating { Star = 4 });

                if (SearchPara.StarStart <= 5 && SearchPara.StarEnd >= 5)
                    rating.Add(new StarRating { Star = 5 });

                if (SearchPara.StarStart <= 0 && SearchPara.StarEnd >= 0)
                    rating.Add(new StarRating { Star = 0 });
                return rating;
            }
            catch (Exception ex)
            {
                _exception.Error(ex);
                return rating;
            }
        }

        public async Task<DataTable> ProcessForPrefferedHotel(HotelSearchParameter SearchPara, int giataid, int IsPrefered)
        {
            DataTable dtPreferredDataHotel = new DataTable();
            dtPreferredDataHotel.Columns.Add("Hotelcode", typeof(string));
            dtPreferredDataHotel.Columns.Add("GiataId", typeof(int));
            dtPreferredDataHotel.Columns.Add("ServiceName", typeof(string));
            try
            {
                if (SearchPara.IsSearchFor.ToLower().IndexOf("preferred") >= 0)
                {
                    try
                    {
                        dtPreferredDataHotel = await GetPreferredDataHotel(Convert.ToInt32(SearchPara.CityID), giataid, IsPrefered);
                    }
                    catch (Exception ex)
                    {
                        await _exception.Error(ex, SearchPara.SearchKey);
                    }
                }
            }
            catch (Exception ex)
            {
                await _exception.Error(ex, SearchPara.SearchKey);
            }

            return dtPreferredDataHotel;
        }

