        public List<SupplierSearchConfig> GetSearchConfig(List<SupplierSearchConfig> lstdtSupplierSearchConfig, Int64 SupplierID, HotelSearchParameter SearchPara)
        {
            List<SupplierSearchConfig> OTHSearchConfig = new List<SupplierSearchConfig>();
            try
            {
                foreach (SupplierSearchConfig conf in lstdtSupplierSearchConfig)
                {
                    if (conf.SupplierID == SupplierID)
                    {
                        if ((conf.CityID == SearchPara.CityID || conf.CityID == 0) && (conf.CountryId == 0 || conf.CountryId.ToString() == Convert.ToString(SearchPara.CountryID)) && (conf.Stars == 0 || conf.Stars >= SearchPara.StarStart && conf.Stars <= SearchPara.StarEnd) && conf.RoomNo >= SearchPara.Rooms.Count && (conf.Hit == (SearchPara.IsWebsite - 1) || SearchPara.IsWebsite == 0))
                            OTHSearchConfig.Add(conf);
                    }
                }
            }
            catch (Exception ex)
            {
                _exception.Error(ex);
            }
            return OTHSearchConfig;
        }

