        public CommonHotelCodes FilterHotelCodeTechWise(DataTable lstdtHotelCommon, int CityID, bool SearchByHotel, int min, int max, int IsRecommendedOnly, DataTable DtOTH = null, List<Int64> GId = null)
        {
            CommonHotelCodes list = new CommonHotelCodes();
            list.OTH_Codes = null;
            list.RateGain_Codes = null;
            list.Siteminder_Codes = null;
            list.hotelrunner_Codes = null;
            list.Travelclick_Codes = null;
            list.ratetiger_Codes = null;
            list.DerbySoft_Codes = null;
            list.Staah_Codes = null;

            list.HotelBeds_Codes = null;
            list.Juniper_Codes = null;
