            list.GoGlobal_Codes = null;
            list.Traveloka_Codes = null;
            list.Paximum_Codes = null;
            list.uk_travco_Codes = null;
            list.Yalago_Codes = null;
            list.Hotelspro_Codes = null;
            list.Nuitee_Codes = null;
            list.GRNC_Codes = null;
            list.Darina_Codes = null;
            list.TBO_Codes = null;
            list.DiscoverSaudi_Codes = null;
            list.Rakuten_Codes = null;
            list.InfiniteHotelsFrance_Codes = null;
            list.Restel_Codes = null;
            list.TravelLanda_Codes = null;
            list.Adonis_Codes = null;
            list.Jumeirah_Codes = null;
            list.saltours_Codes = null;
            list.Techno_Codes = null;
            list.bookingv3_Codes = null;
            list.HotelTrader_Codes = null;
            list.Parsec_Codes = null;
            list.ETG_Codes = null;
            list.Rezlive_Codes = null;
            list.HotelsTrack_Codes = null;
            list.PkFare_Codes = null;
            list.Price_Travel_Codes = null;
            list.LetsFly_Codes = null;
            list.Dingus_codes = null;
            list.Elevateholidays_codes = null;
            list.Welcomebeds_Codes = null;
            list.Exely_Codes = null;
            list.Techno_New_Codes = null;
            list.DirectConracting_Codes = null;

            try
            {
                #region"Filter HotelCodes"


                string key = "Codes_new1_" + CityID + "_" + min + "_" + max + "_" + DateTime.Now.Date.Day + "_" + IsRecommendedOnly;
                bool found = false;
                if (_cache.Get(key) != null && SearchByHotel == false)
                {
                    list = (CommonHotelCodes)(_cache.Get(key));
                    if (list == null)
                        found = false;
                    else
                        found = true;
                }


                if (found == false)
                {
                    if (lstdtHotelCommon != null)//@new7-12-22
                    {
                        //DataTable dt = lstdtHotelCommon.DefaultView.ToTable(true, "SupplierName");
                        DataTable dt = lstdtHotelCommon.DefaultView.ToTable(true, "TechName");
                        for (int i = 0; i < dt.Rows.Count; i++)
                        {
                            string SuppplierCheck = Convert.ToString(dt.Rows[i]["TechName"]).ToLower();

                            try
                            {
                                switch (SuppplierCheck.ToLower())
                                {
                                    #region"OTH"
                                    case "oth":
                                    case "withinearth":
                                        if (DtOTH != null && DtOTH.Rows.Count > 0)
                                        {
                                            if (SearchByHotel)
                                            {
                                                if (GId.Count > 0)
                                                    list.OTH_Codes = DtOTH.Select("giataid IN (" + string.Join(",", GId) + ") and Supplier='oth'");
                                            }
                                            else
                                                list.OTH_Codes = DtOTH.Select("Supplier='oth'");
                                        }
                                        break;

                                    #endregion
                                    #region"RateGain"
                                    case "rategain":
                                        if (DtOTH != null && DtOTH.Rows.Count > 0)
                                        {
                                            if (SearchByHotel)
                                            {
                                                if (GId.Count > 0)
                                                    list.RateGain_Codes = DtOTH.Select("giataid IN (" + string.Join(",", GId) + ") and Supplier='rategain'");
