                                        }
                                        break;
                                    #endregion
                                    #region"Siteminder"
                                    case "siteminder":
                                        if (DtOTH != null && DtOTH.Rows.Count > 0)
                                        {
                                            if (SearchByHotel)
                                            {
                                                if (GId.Count > 0)
                                                    list.Siteminder_Codes = DtOTH.Select("giataid IN (" + string.Join(",", GId) + ") and Supplier='siteminder'");
                                            }
                                            else
                                                list.Siteminder_Codes = DtOTH.Select("Supplier='siteminder'");
                                        }
                                        break;
                                    #endregion
                                    #region"hotelrunner"
                                    case "hotelrunner":
                                        if (DtOTH != null && DtOTH.Rows.Count > 0)
                                        {
                                            if (SearchByHotel)
                                            {
                                                if (GId.Count > 0)
                                                    list.hotelrunner_Codes = DtOTH.Select("giataid IN (" + string.Join(",", GId) + ") and Supplier='hotelrunner'");
                                            }
                                            else
                                                list.hotelrunner_Codes = DtOTH.Select("Supplier='hotelrunner'");
                                        }
                                        break;
                                    #endregion
                                    #region"Travelclick"
                                    case "travelclick":
                                        if (DtOTH != null && DtOTH.Rows.Count > 0)
                                        {
                                            if (SearchByHotel)
                                            {
                                                if (GId.Count > 0)
                                                    list.Travelclick_Codes = DtOTH.Select("giataid IN (" + string.Join(",", GId) + ") and Supplier='travelclick'");
                                            }
                                            else
                                                list.Travelclick_Codes = DtOTH.Select("Supplier='travelclick'");
                                        }
                                        break;
                                    #endregion
                                    #region"Dedge"
                                    case "dedge":
                                        if (DtOTH != null && DtOTH.Rows.Count > 0)
                                        {
                                            if (SearchByHotel)
                                            {
                                                if (GId.Count > 0)
                                                    list.Dedge_Codes = DtOTH.Select("giataid IN (" + string.Join(",", GId) + ") and Supplier='dedge'");
                                            }
                                            else
                                                list.Dedge_Codes = DtOTH.Select("Supplier='dedge'");
                                        }
