        public async Task<DataSet> GetHotelDataForListFinalNewSpeedVinod_Redis_New(int cityid, int countryid, int refreshCache, bool oneid, string hotelid, int agentId, (List<RaynaXML.Root> DB0, string DB1, List<HashSet<int>> DB2, Dictionary<int, HashSet<int>> DB3, Dictionary<int, HashSet<int>> DB4) redisData)
        {
            var ds = new DataSet();

            try
            {
                var DB0 = redisData.DB0; // Rayan + XML data (list of JSON)



                var DB1 = redisData.DB1; // Supplier SpeedCategory (single JSON string)
                List<HashSet<int>> DB2 = redisData.DB2; // Supplier SpeedCategory (single JSON string) 0:AITO_Exclude_Agent, 1:AITO_Include_Agent, 2:BaseHotelID
                //Dictionary<int, List<int>> DB3 = redisData.DB3;
                //Dictionary<int, List<int>> DB4 = redisData.DB4;
                Dictionary<int, HashSet<int>> DB3fast = redisData.DB3;
                Dictionary<int, HashSet<int>> DB4fast = redisData.DB4;

                HashSet<int> AITO_Exclude_Agent = DB2[0];
                HashSet<int> AITO_Include_Agent = DB2[1];
                HashSet<int> BaseHotelID = DB2[2];

                // ==========================
                // DB3 + DB4 to HashSet for O(1)
                // ==========================
                //var DB3fast = DB3.ToDictionary(
                //    x => x.Key,
                //    x => x.Value.ToHashSet()
                //);

                //var DB4fast = DB4.ToDictionary(
                //    x => x.Key,
                //    x => x.Value.ToHashSet()
                //);

                if (DB0 == null || DB0.Count == 0 || string.IsNullOrEmpty(DB1))
                    return ds; // no data, return empty dataset

                // ✅ Deserialize SpeedCategory JSON (faster with source generator)
                var speedCat = System.Text.Json.JsonSerializer.Deserialize(DB1, JsonContexts.Default.SpeedCategoryRoot);
                bool IncludeBaseID = speedCat != null && speedCat.IncludeBaseID == 1;
                bool ActiveSelfLearning = speedCat?.ActiveSelfLearning == 1;
                bool CurrentAITO_Status = speedCat?.CurrentAITO_Status == 1;
                bool Agt_SupTopselling_Base = speedCat?.Agt_SupTopselling_Base == 1;

                // -------------------------------------------------------------
                // Pre-deserialize all hotel JSONs (fastest)
                // -------------------------------------------------------------
                int size = DB0.Count;
                var hotelArray = DB0; // new RaynaXML.Root[size];

                //for (int i = 0; i < size; i++)
                //{
                //    var json = DB0[i];
                //    if (string.IsNullOrWhiteSpace(json))
                //    {
                //        hotelArray[i] = null; // skip empty entries
                //        continue;
                //    }

                //    try
                //    {
                //        hotelArray[i] = System.Text.Json.JsonSerializer.Deserialize(json, JsonContexts.Default.RaynaRoot);
                //    }
                //    catch
                //    {
                //        hotelArray[i] = null; // safely ignore deserialization errors
                //    }
                //}


                // -----------------------------------------------------------------
                // STEP 2: Apply AITO filter BEFORE starting parallel processing
                // -----------------------------------------------------------------
                List<RaynaXML.Root> filteredHotels;

                if (ActiveSelfLearning && CurrentAITO_Status)
                {
                    filteredHotels = hotelArray
                        .Where(root =>
                        {
                            if (root == null) return false;
                            int id = root.RaynaId;

                            // EXCLUDE FIRST
                            if (AITO_Exclude_Agent.Contains(id))
                                return false;

                            // INCLUDE DIRECT ALWAYS TRUE
                            if (AITO_Include_Agent.Contains(id))
                                return true;

                            // Include BaseHotel only when IncludeBaseID = 1
                            if (IncludeBaseID && BaseHotelID.Contains(id))
                                return true;

                            return false;
                        })
                        .ToList();
                }
                else
                {
                    // No AITO filter
                    filteredHotels = hotelArray
                        .Where(root =>
                        {
                            if (root == null) return false;
                            int id = root.RaynaId;

                            // EXCLUDE FIRST
                            if (AITO_Exclude_Agent.Contains(id))
                                return false;

                            return true;
                        })
                        .ToList();
                }



                //// Build allowed supplier list
                //var allowedSupplierIds =
                //    speedCat?.Suppleir?
                //    .Where(s => s.ActiveStatus == 1)
                //    .Select(s => s.SupplierID)
                //    .ToHashSet()
                //    ?? new HashSet<int>();

                // Precompute allowed suppliers (active only)
                var allowedSupplierIds = new HashSet<int>();
                if (speedCat?.Suppleir != null)
                {
                    foreach (var s in speedCat.Suppleir)
                    {
                        if (s?.ActiveStatus == 1)
                            allowedSupplierIds.Add(s.SupplierID);
                    }
                }

                //var Agt_SupTopselling =
                // speedCat?.Suppleir?
                // .Where(s => s.Agt_SupTopselling == 1)
                // .Select(s => s.SupplierID)
                // .ToHashSet()
                // ?? new HashSet<int>();

                // Thread-safe collections for parallel processing
                var giataList = new ConcurrentBag<GiataDetailsRow>();
                var mappingList = new ConcurrentBag<MappingDetailsRow>();

                // -------------------------------------------------------------
                // PARALLEL HOTEL FILTERING + MAPPING (FASTEST PART)
                // -------------------------------------------------------------
                Parallel.ForEach(filteredHotels, root =>
                {
                    // ----------------- GIATA INFO ------------------
                    giataList.Add(new GiataDetailsRow
                    {
                        RaynaId = root.RaynaId,
                        Rating = root.Rating,
                        CountryId = root.CountryId,
                        CityId = root.CityId,
                        GiataId = root.giataid,
                        IsRecomondedHotel = root.IsRecomondedHotel,
                        HotelContactNo = root.HotelContactNo,
                        ReservationEmail = root.ReservationEmail,
                        HotelName = root.HotelName
                    });

                    // ----------------- MAPPING INFO ----------------
                    foreach (var map in root.XMLMappings)
                    {
                        if (!allowedSupplierIds.Contains(map.SupplierId))
                        {
                            continue;
                        }
                        if (Agt_SupTopselling_Base /* && Agt_SupTopselling.Contains(map.SupplierId)*/ && DB3fast.TryGetValue(map.SupplierId, out var hotelIdList))
                        {
                            // Supplier exists → check if hotel is inside DB3 list
                            if (!hotelIdList.Contains(map.RaynaId))
                            {
                                // ❌ hotelId not allowed → skip
                                continue;
                            }
                        }
                        else
                        {
                            if (DB4fast.TryGetValue(map.SupplierId, out var hotelIdListt))
                            {
                                if (!hotelIdListt.Contains(map.RaynaId))
                                {
                                    // ❌ hotelId not allowed → skip
                                    continue;
                                }
                            }
                        }


                        mappingList.Add(new MappingDetailsRow
                        {
                            XmlId = map.XmlId,
                            RaynaId = map.RaynaId,
                            OwnsystemHotelId = map.OwnsystemHotelId,
                            XmlBaseId = map.XmlBaseId,
                            supplierName = map.supplierName,
                            SupplierId = map.SupplierId,
                            GiataId = map.GiataId,
                            CityId = map.CityId,
                            TechName = string.Equals(map.TechName, "direct", StringComparison.OrdinalIgnoreCase)
                                ? map.supplierName
                                : map.TechName
                        });
                    }
                });

                // ✅ Convert lists to DataTables once
                var giataDt = _commonMethod.GenerateGiataDetails();
                var mapDt = _commonMethod.GenerateMappingDetails();

                foreach (var g in giataList)
                    giataDt.Rows.Add(g.RaynaId, g.Rating, g.CountryId, g.CityId, g.GiataId, g.IsRecomondedHotel, g.HotelContactNo, g.ReservationEmail, g.HotelName);

                foreach (var m in mappingList)
                    mapDt.Rows.Add(m.XmlId, m.RaynaId, m.OwnsystemHotelId, m.XmlBaseId,
                                   m.supplierName, m.SupplierId, m.GiataId, m.CityId, m.TechName);

                ds.Tables.Add(giataDt);
                ds.Tables.Add(mapDt);
            }
            catch (Exception ex)
            {
                _ = _exception.Error(ex);
            }

            return ds;
        }

