        public async Task<DataSet> GetHotelDataForListFinalNewSpeed(int cityid, int countryid, int RefreshCache, bool oneid, string hotelid, int AgentId)
        {

            try
            {
                countryid = 0;
                DataSet CityWiseHotelInformation = new DataSet();
                //string folderpath = Convert.ToString(_keySettings.staticHoteldata) + (oneid ? "HotelId/" + hotelid + "/" : "");
                string folderpath = Convert.ToString(_keySettings.staticHoteldata_newapi) + (oneid ? "HotelId/" + hotelid + "/" : "");
                string path = folderpath + "HotelInfomationAPI_" + cityid + "_" + hotelid + ".json";

                if (!Directory.Exists(folderpath))
                    Directory.CreateDirectory(folderpath);
                if (System.IO.File.Exists(path) && RefreshCache == 0)
                {
                    Newtonsoft.Json.JsonSerializer serializer = new Newtonsoft.Json.JsonSerializer();
                    try
                    {
                        using (FileStream s = File.Open(path, FileMode.Open, FileAccess.Read, FileShare.Read))
                        {

                            using (StreamReader sr = new StreamReader(s))
                            {
                                using (JsonReader reader = new JsonTextReader(sr))
                                {
                                    while (reader.Read())
                                    {
                                        if (reader.TokenType == JsonToken.StartObject)
                                        {
                                            CityWiseHotelInformation = serializer.Deserialize<DataSet>(reader);
                                        }
                                    }
                                }
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        await _exception.Error(ex);
                        try
                        {
                            File.Delete(path);
                        }
                        catch (Exception exx)
                        {

                            await _exception.Error(exx);
                        }
                    }
                    finally
                    {
                    }
                }
                else
                {
                    if (oneid)
                    {
                        try
                        {
                            SqlParameter[] para = new SqlParameter[]{
                         new SqlParameter("@CityId",  cityid),
                         new SqlParameter("@hotelid",  hotelid),
                         new SqlParameter("@AgentId",  AgentId)

                      };
                            if (_keySettings.Use_ReplicationDB == "1")
                                CityWiseHotelInformation = await _dlConnection.GetDataSet_ReplicationDB("GetHotelDataForList_category_byhotel", para, 600);
                            else
                                CityWiseHotelInformation = await _dlConnection.GetDataSet("GetHotelDataForList_category_byhotel", para);
                        }
                        catch (Exception ex)
                        {
                            await _exception.Error(ex);
                        }
                    }
                    else
                    {
                        try
                        {
                            SqlParameter[] para = new SqlParameter[]{
                         new SqlParameter("@CityId",  cityid),
                         new SqlParameter("@AgentId",  AgentId)
                      };
                            if (_keySettings.Use_ReplicationDB == "1")
                                //CityWiseHotelInformation = await _dlConnection.GetDataSet_ReplicationDB("GetHotelDataForList_category", para, 600);
                                CityWiseHotelInformation = await _dlConnection.GetDataSet_ReplicationDB("GetHotelDataForList_category_new9", para, 600);
                            else
                                //CityWiseHotelInformation = await _dlConnection.GetDataSet("GetHotelDataForList_category", para);
                                CityWiseHotelInformation = await _dlConnection.GetDataSet("GetHotelDataForList_category_new9", para);
                        }
                        catch (Exception ex)
                        {
                            await _exception.Error(ex);
                        }

                    }
                    if (CityWiseHotelInformation.Tables.Count > 0)
                    {
                        CityWiseHotelInformation.Tables[0].TableName = "GiataDetails";
                        CityWiseHotelInformation.Tables[1].TableName = "MappingDetails";
                    }
                    if (CityWiseHotelInformation.Tables.Count > 0)
                    {
                        GenerateGiataDataColumns(ref CityWiseHotelInformation);
                        if (CityWiseHotelInformation.Tables[0].Rows.Count > 0)
                        {
                            string json = Newtonsoft.Json.JsonConvert.SerializeObject(CityWiseHotelInformation);
                            if (json != "{}")
                            {
                                FileStream fs1 = new FileStream(path, FileMode.OpenOrCreate, FileAccess.ReadWrite, FileShare.ReadWrite);
                                try
                                {
                                    fs1.SetLength(0);
                                    using (StreamWriter sw = new StreamWriter(fs1))
                                    {
                                        sw.WriteLine(json);
                                    }
                                }
                                finally
                                {
                                    fs1.Close();
                                    fs1.Dispose();
                                }
                            }
                        }
                    }
                }


                return CityWiseHotelInformation;
            }
            catch (Exception ex)
            {
                await _exception.Error(ex);
                return null;
            }
        }

