        public byte[] CompressNew(byte[] input, string compressionMethod) //New Added on 10-FEB-26
        {
            if (compressionMethod.Equals("gzip", StringComparison.OrdinalIgnoreCase))
            {
                // GZip compression
                using (var ms = new MemoryStream())
                {
                    using (var gzip = new GZipStream(ms, CompressionLevel.Fastest, leaveOpen: true))
                    {
                        gzip.Write(input, 0, input.Length);
                    }
                    return ms.ToArray();
                }
            }
            else if (compressionMethod.Equals("deflate", StringComparison.OrdinalIgnoreCase))
            {
                // ZLIB-wrapped DEFLATE (RFC 1950)
                using (var ms = new MemoryStream())
                {
                    // 1. Write ZLIB header (default compression)
                    ms.WriteByte(0x78);
                    ms.WriteByte(0x9C);



                    // 2. Compress raw DEFLATE
                    using (var deflate = new DeflateStream(ms, CompressionLevel.Fastest, leaveOpen: true))
                    {
                        deflate.Write(input, 0, input.Length);
                    }



                    // 3. Calculate Adler-32 checksum
                    uint adler = Adler32(input);



                    // 4. Write checksum (big-endian)
                    ms.WriteByte((byte)((adler >> 24) & 0xFF));
                    ms.WriteByte((byte)((adler >> 16) & 0xFF));
                    ms.WriteByte((byte)((adler >> 8) & 0xFF));
                    ms.WriteByte((byte)(adler & 0xFF));



                    return ms.ToArray();
                }
            }
            else
            {
                throw new NotSupportedException($"Compression method '{compressionMethod}' is not supported.");
            }
        }
        private uint Adler32(byte[] data) //New Added on 10-FEB-26
        {
            const uint MOD_ADLER = 65521;
            uint a = 1, b = 0;



            foreach (var c in data)
            {
                a = (a + c) % MOD_ADLER;
                b = (b + a) % MOD_ADLER;
            }



            return (b << 16) | a;
        }


        private byte[] Compress(byte[] input, string compressionMethod)
        {
            using (var ms = new MemoryStream())
            {
                Stream compressionStream = compressionMethod.ToLower() == "gzip"
                    ? (Stream)new GZipStream(ms, CompressionMode.Compress)
                    : new DeflateStream(ms, CompressionMode.Compress);

                compressionStream.Write(input, 0, input.Length);
                compressionStream.Close();
                return ms.ToArray();
            }
        }

        public async Task<ApiRequest<T>> SendRequestAsyncNew<T>(string apiUrl, string requestPayload, string apiName = "") //apiName added on 04-06-25
        {
            var responseObject = new ApiRequest<T>();
            try
            {
                ApiResponse responseContent = await GetSupplierResponseNew(apiUrl, requestPayload, apiName); //apiName added on 04-06-25
                //responseObject.Response = System.Text.Json.JsonSerializer.Deserialize<T>(responseContent.response);

                if (responseContent.response == "401")
                {
                    responseObject.StatusCode = responseContent.StatusCode;
                }
                else
                {
                    responseObject.Response = Newtonsoft.Json.JsonConvert.DeserializeObject<T>(responseContent.response);
                    responseObject.StatusCode = responseContent.StatusCode; // Assuming success
                }


            }
            catch (Exception ex)
            {
                if (apiName == "book" || apiName == "bookingdetail")
                    _ = _exception.ErrorBooking(ex, "");
                else
                    _ = _exception.Error(ex);

                responseObject.StatusCode = 500; // Or any appropriate error code
            }
            return responseObject;
        }

        public async Task<ApiResponse> GetSupplierResponseNew(string apiURL, string Request, string apiName = "") //apiName added on 04-06-25
        {
            ApiResponse res = new ApiResponse();
            try
            {
                var handler = new HttpClientHandler
                {
                    AutomaticDecompression = DecompressionMethods.Deflate | DecompressionMethods.GZip
                };

                using var httpClient = new HttpClient(handler);

                // Add headers to mimic Postman
                httpClient.DefaultRequestHeaders.Accept.Add(new MediaTypeWithQualityHeaderValue("application/json"));
                httpClient.DefaultRequestHeaders.AcceptEncoding.Add(new StringWithQualityHeaderValue("deflate"));
                httpClient.DefaultRequestHeaders.AcceptEncoding.Add(new StringWithQualityHeaderValue("gzip"));

                if (apiName.ToLower() == "recheck")
                    httpClient.Timeout = TimeSpan.FromMilliseconds(60000);
                else
                    httpClient.Timeout = TimeSpan.FromMilliseconds(300000);



                // Optional: If Postman adds Authorization header
                // httpClient.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", "YOUR_TOKEN");

                var json = System.Text.Json.JsonSerializer.Serialize(Request);
                var content = new StringContent(Request, Encoding.UTF8, "application/json");

                var response = await httpClient.PostAsync(apiURL, content);
                string responseContent = await response.Content.ReadAsStringAsync();

                res.response = responseContent;
                res.StatusCode = (int)response.StatusCode;

                try
                {
                    if (apiName == "book" || apiName == "bookingdetail")
                        _ = Task.Run(() => _exception.getException_v1(res.response, Request, apiName, apiURL, "NewApiResponse", Convert.ToString(res.StatusCode)));
                }
                catch (Exception)
                {

                }


                return res;
            }
            catch (Exception ex)
            {
                if (apiName == "book" || apiName == "bookingdetail")
                    _ = _exception.ErrorBooking(ex, "");
                else
                    _ = _exception.Error(ex);

                return res;

            }


        }

        public HttpStatusCode GetStatusCode(int statusCode)
        {
            switch (statusCode)
            {
                case 200:
                    return HttpStatusCode.OK;
                case 401:
                    return HttpStatusCode.Unauthorized;
                case 500:
                    return HttpStatusCode.InternalServerError;
                default:
                    return HttpStatusCode.InternalServerError;
                    break;
            }
            return HttpStatusCode.InternalServerError;
        }

