            }
        }


        public static bool RoomDiffChk(HotelSearchParameter SearchPara)
        {
            bool IsSame = true;
            for (int i = 0; i < SearchPara.Rooms.Count; i++)
            {
                int NoOfAdt = SearchPara.Rooms[0].NoofAdults;
                int NoOfChd = SearchPara.Rooms[0].NoofChild;
                int Child1Age = SearchPara.Rooms[0].Child1Age;
                int Child2Age = SearchPara.Rooms[0].Child2Age;
                if (NoOfAdt != SearchPara.Rooms[i].NoofAdults || NoOfChd != SearchPara.Rooms[i].NoofChild || Child1Age != SearchPara.Rooms[i].Child1Age || Child2Age != SearchPara.Rooms[i].Child2Age)
                    IsSame = false;
            }
            return IsSame;
        }

