        public async Task<string> GetTechNameBySupplierName(string SupplierName, string TenantId = "")
        {
            string TechName = "";
            try
            {
                SupplierName = SupplierName == "oth" ? Convert.ToString(_keySettings.IsWithinearth) == "1" ? "withinearth" : "oth" : SupplierName;
                string keydata = "GetTechNameOfSupplierId_" + Convert.ToString(SupplierName);
                DataTable dtTechName = new DataTable();
                if (!_cache.TryGetValue(keydata, out dtTechName))
                {
                    SqlParameter[] para = new SqlParameter[] {
                                            new SqlParameter("@SupplierName",SupplierName),
                                            new SqlParameter("@TenantId",TenantId),
                                            };
                    dtTechName = await _dlConnection.GetDataTableAsync("GetTechNameBySupplierName", para);//@HID
                    if (dtTechName.Rows.Count > 0)
                    {
                        _cache.Set(keydata, dtTechName, new MemoryCacheEntryOptions().SetAbsoluteExpiration(DateTime.Now.AddHours(1)));
                    }
                }

                TechName = Convert.ToString(dtTechName.Rows[0]["TechName"]);
            }
            catch (Exception EA)
            {
                await _exception.Error(EA);
                TechName = "";
            }
            return TechName;
        }
        #endregion

