        public async Task<CancellationPilicyRS_newapi> GetCancellationPolicy(CancellationPolicyRQ policyRQ, TokenData tokenData, AdvancedOptions advancedOptions, string userAgent, string IP)
        {
            DataTable dtROE = tokenData.dtROE;
