            string SupplierID = policyRQ.HotelOptionId.Split('|')[Convert.ToInt16(_cacheHotelOption.supplierId)];
            int HotelSquence_RQ = Convert.ToInt32(policyRQ.HotelOptionId.Split('|')[Convert.ToInt16(_cacheHotelOption.hotelSeq)]);

            CacheRoomToken cacheRoomToken = policyRQ.RoomToken.DecryptCacheRoomToken();
            int giataid_Seq_Found = 0; int hotelid_Seq_Found = 0;
            int status = 0;
            AvailHotelList finalResponse = new AvailHotelList();
            //Options selectedOption = CacheMaster.LoadHotelfromMainCache(ref availResponse, policyRQ.Searchkey, tokenData, OwnsystemHotelId, SupplierID, giataSequence_RQ, HotelSquence_RQ, ref giataid_Seq_Found, ref hotelid_Seq_Found, ref status);
