                    await _exception.Error(ex);
                }
            }



            policyResponse.CancellationPolicy = lstPolicy;
            cancellationResponse.CancellationRS = policyResponse;

            cancellationResponse_1.CancellationPilicyRS = cancellationResponse;
            return cancellationResponse_1;
        }

