                                        await _commonMethod.AUTO_DeactiveHotel(Rayna_ID, tokenData.AgentId, objdata.SupplierName, "Prebook");
                                    }
                                    catch (Exception x)
                                    {
                                        _ = _exception.Error(x);
                                    }
                                    timerPreBook.Stop();
                                    PreBookTime = PreBookTime + ",| after AutoSupplierHotelSusspend time:" + timerPreBook.Elapsed.ToString();
                                    timerPreBook.Restart();
                                }
                            }
                            catch (Exception x)
                            {
                                _ = _exception.Error(x);
                            }
                            #endregion
                        }
                        if (preBookRS.HotelOption != null && preBookRS.HotelOption.Status == PreBookStatus.NotAllowed)
                        {
                            preBookResponse.Error.Add(GetErrorMsg(ErrorType.NoPermission, ErrorCode.NoPermission, "Your credit limit is insufficient or booking within cancellation deadline is not allowed"));
                        }
                        if (dtPolicy != null)
                        {
                            for (int i = 0; i < dtPolicy.Rows.Count; i++)
                            {
                                if (Convert.ToString(dtPolicy.Rows[i]["CartID"]) == "")
                                    dtPolicy.Rows[i]["CartID"] = UserCartId;
                            }
                        }

                        if (dtRateBreakUp != null)
                        {
                            if (!dtRateBreakUp.Columns.Contains("CartID"))
                                dtRateBreakUp.Columns.Add("CartID", typeof(string));
                            dtRateBreakUp.AcceptChanges();
                            for (int i = 0; i < dtRateBreakUp.Rows.Count; i++)
                            {
                                dtRateBreakUp.Rows[i]["CartID"] = UserCartId;
                            }

                        }
                        if (dtCartTable != null)
                        {
                            for (int i = 0; i < dtCartTable.Rows.Count; i++)
                            {
                                dtCartTable.Rows[i]["UserCartId"] = UserCartId;
                            }

                        }
                        if (dtRateBreakUp != null && dtPolicy != null && dtPolicy.Rows.Count > 0)
                            await AddPolicyAndRateInDatabase(dtPolicy, dtRateBreakUp, dtCartTable);
                        else
                            preBookResponse.Error.Add(GetErrorMsg(ErrorType.GeneralError, ErrorCode.NorecordError, ErrorDescription.PolicyNotFound));

                        try
                        {
                            String dtPolicy_str = JsonConvert.SerializeObject(dtPolicy);// added on 26-9-2024
                            _ = _exception.getException_v1(dtPolicy_str, "dtPolicy_str", Convert.ToString(UserCartId), "", SearchKey);

                            try
                            {
                                SqlParameter[] paranew = new SqlParameter[]{
                                new SqlParameter("@Json",dtPolicy_str),
                                new SqlParameter("@SearchKey",SearchKey),
                                new SqlParameter("@UserCartId",UserCartId)
                                };
                                await _dlConnection.GetExecuteScalarSP("SavedtPolicy_Xconnect", paranew);

                            }
                            catch (Exception ex)
                            {
                                _ = _exception.ErrorBooking(ex, "", "", "SavedtPolicy_Xconnect");
                            }

                            //DataTable dt = (DataTable)JsonConvert.DeserializeObject(dtPolicy_str, typeof(DataTable));
                        }
                        catch (Exception q)
                        {
                            _ = _exception.Error(q);
                        }

                    }
                    else
                    {
                        return null;
                    }
                }
                else
                {
                    preBookResponse.Error.Add(GetErrorMsg(ErrorType.NoPermission, ErrorCode.NoPermission, ErrorDescription.NoPermission));
                }
                preBookResponse.PreBookRS = preBookRS;

                try
                {
                    timerPreBook.Stop();
                    _ = _exception.getException_v1("", "PreBookTime", PreBookTime, "XMLOUT", SearchKey, PreBookTime);
                }
                catch (Exception ex)
                {
                    _ = _exception.Error(ex, SearchKey);
                }

                preBookResponse_1.PreBookResponse = preBookResponse;
                return preBookResponse_1;

            }
            catch (Exception ex)
            {
                _ = _exception.Error(ex);
                return null;
            }
        }

        public async Task<PreBookResponse_newapi> PreBook(PreBookRequest prebookRQ, TokenData tokenData, AdvancedOptions advancedOptions, string JsonRQ, string userAgent, string IP, string HostName, string token)
        {
            PreBookResponse_newapi preBookResponse_1 = new PreBookResponse_newapi();
