                        for (int i = 0; i < BookOption.Rooms[r].PolicyDetails.Count; i++)
                        {
                            //BookOption.Rooms[r].HotelRooms.EssentialInformation = "";//@New
                            bool IsJuniper = false;
                            //IsJuniper = _commonMethod.IsJuniperCheck(BookOption.Rooms[r].HotelRooms.SupplierName.ToLower());
