                {
                    decimal AgentBuy = Convert.ToInt32(IsCombineRoom ? RoomNo == 1 ? Convert.ToDecimal(BookOption.Rooms[index].HotelRooms.AgentBuyingPrice) : value : Convert.ToDecimal(BookOption.Rooms[index].HotelRooms.AgentBuyingPrice));
