                        obj.LoyaltyPoints = Convert.ToInt32(Math.Round((AgentBuy.Equals(DBNull.Value) ? 0 : AgentBuy * Convert.ToDecimal(datarow[0]["HotelPercentage"]) / 100) * Convert.ToDecimal(datarow[0]["HotelCounter"])));
