            }
            return obj;
        }

        public async Task<DataSet> GetAgentRightsAndDetails(TokenData tokenData, int InCancellation, int IsDetailsOnly, string TockenNoValue = "")
        {
            try
            {
                // --@InCancellation 0 means Refundable 1 means NRF
                //--@IsDetailsOnly 0 means only details else rights
                SqlParameter[] para = new SqlParameter[]{
               new SqlParameter("@AgentId", Convert.ToString(tokenData.Type).ToLower() == "subagent" ? Convert.ToInt32(tokenData.ParentId) : Convert.ToInt32(tokenData.AgentId)),
               new SqlParameter("@SubUserId",tokenData.SubUserId),
               new SqlParameter("@AgentCode",tokenData.AgentCode),
               new SqlParameter("@InCancellation",InCancellation),
               new SqlParameter("@TockenNoValue",TockenNoValue),
               new SqlParameter("@IsDetailsOnly",IsDetailsOnly)

            };

                DataSet ds = await _dlConnection.GetDataSet("GetAgentRightsAndDetails_Xconnect", para);
                if (ds != null && ds.Tables.Count > 0)
                {
                    switch (IsDetailsOnly)
                    {
                        case 0:
                            ds.Tables[0].TableName = "AgentDetails";
                            break;
                        case 1:
                            ds.Tables[0].TableName = "AgentDetails";
                            ds.Tables[1].TableName = "AgentRights";
                            break;
                        default:
                            break;
                    }

                }
                return ds;
            }
            catch (Exception ex)
            {
                _ = _exception.Error(ex);
                return null;
            }

        }

        public async Task<int> SaveCartForHotelNew(Shopping_CartDataForHotelXML cart, Int32 Rayna_ID, string IP)
        {
            int SubUserId = 0;
            SubUserId = cart.AgentId; ; // after change

            try
            {
                DataTable RoomDetails = HtmlExtensions.ConvertToDataTable(cart.ShoppingCartDetails);
                RoomDetails.Columns.Remove("SupplierId");
                RoomDetails.Columns.Remove("MealAdultRate");
                RoomDetails.Columns.Remove("MealChildRate");
                RoomDetails.Columns.Remove("VATAmount");

                SqlParameter[] para = new SqlParameter[]{
                 new SqlParameter("@GuestUserId",  cart.GuestUserId),
                 new SqlParameter("@ServiceType",  cart.ServiceType),
                 new SqlParameter("@ServiceId",  cart.ServiceId),
                 new SqlParameter("@ServiceName",  cart.ServiceName),
                 new SqlParameter("@ImagePath", cart.ImagePath==null ?"":cart.ImagePath),
                 new SqlParameter("@CheckInDate",  cart.CheckInDate),
                 new SqlParameter("@CheckOutDate",  cart.CheckOutDate),
                 new SqlParameter("@TourDuration",  cart.TourDuration==null?"0":cart.TourDuration),
                 new SqlParameter("@TourStartTime",  cart.TourStartTime==null ? "00:00:00" : cart.TourStartTime),
                 new SqlParameter("@NoOfAdults",  cart.NoOfAdults),
                 new SqlParameter("@NoOfChild",  cart.NoOfChild),
                 new SqlParameter("@AdultRate",  cart.AdultRate),
                 new SqlParameter("@ChildRate",  cart.ChildRate),
                 new SqlParameter("@ProductType",  cart.ProductType==null?"":cart.ProductType),
                 new SqlParameter("@BookingStatus",  cart.BookingStatus),
                 new SqlParameter("@VisaReqFor",  cart.VisaReqFor),
                 new SqlParameter("@Nationality",  cart.Nationality),
                 new SqlParameter("@ServiceTotal",  cart.ServiceTotal),
                 new SqlParameter("@IsGuestUser",  cart.IsGuestUser),
                 new SqlParameter("@RoomDetails", RoomDetails),// HotelRepository.ConvertToDataTable<ShoppingCart_DetailsNew>(cart.ShoppingCartDetails)),//CommonExtension.ConvertToDataTable<CouponCartLst>(lstCouponCartLst)
                 new SqlParameter("@IsB2B",  cart.IsB2B),
                 new SqlParameter("@Percentage",  cart.Percentage),
                 new SqlParameter("@XMLHotelId",  cart.XMLHotelId),
                 new SqlParameter("@XMLCityId",  cart.XMLCityId),
                 new SqlParameter("@XMLCountryId",  cart.XMLCountryId),
                 new SqlParameter("@OfficeId",  cart.OfficeId),
                 new SqlParameter("@ContractId",  cart.ContractId),
                 new SqlParameter("@TourOption",  cart.TourOption),
                 new SqlParameter("@IsCombo",  cart.IsCombo),
                 new SqlParameter("@ComboId",  cart.ComboId),
                 new SqlParameter("@AgentId",  SubUserId),
                 new SqlParameter("@EntryDate",  cart.EntryDate),
