        public async Task<DataTable> ProcessPricePoupTable(bool IsRemove, int packageid, int UsercartId, string SupplierCurrency, int Multi, int City, string Country, DataTable dtPriceDetail, DataSet dsAgentDetails, bool IsB2C, bool isPerce, DataTable dtCountryCityMarkup, DataSet dsCartDetails, double AgentMarkupAmount, double UpdatedPrice, double B2CMarkup, double SubAgentMarkup, int IsParentId, double AgentPercentage, int j)
        {
            try
            {
                DataRow dtr = dtPriceDetail.NewRow();
                dtr["HotelName"] = Convert.ToString(dsCartDetails.Tables[1].DefaultView[j]["HotelName"]);
                dtr["RoomType"] = Convert.ToString(dsCartDetails.Tables[1].DefaultView[j]["Roomtype"]);
                dtr["OldPrice"] = Convert.ToDouble(dsCartDetails.Tables[1].DefaultView[j]["FinalSellingPrice"]);
                dtr["SupplierCurrency"] = SupplierCurrency;
                double Vatperice = 0;
                UpdatedPrice = _markup.ProcessHotelRateBreakupPrice_WithMarkup(Multi, City, Country, UpdatedPrice, B2CMarkup, IsParentId, isPerce, AgentPercentage, AgentMarkupAmount, SubAgentMarkup, ref Vatperice);
                dtr["NewPrice"] = UpdatedPrice;
                if (IsRemove)
                {
                    dtr["NewPrice"] = 0;
                    dtr["OldPrice"] = 0;

                }
                dtr["IsRemove"] = IsRemove;
                dtr["PackageId"] = packageid;
                dtr["UserCartId"] = UsercartId;
                DataRow[] drCheck = dtPriceDetail.Select("UserCartId='" + UsercartId + "' and IsRemove=true");
                if (drCheck.Length == 0)
                    dtPriceDetail.Rows.Add(dtr);

                #region SaveCartPriceCheck
                double OldPrice = Convert.ToDouble(dsCartDetails.Tables[1].DefaultView[j]["FinalSellingPrice"]);
                string AgentID = Convert.ToString(dsAgentDetails.Tables[0].Rows[0]["AgentID"]);
                string AgentCode = Convert.ToString(dsAgentDetails.Tables[0].Rows[0]["AgentCode"]);


                await SaveCartPriceCheck(dsCartDetails, j, City, UpdatedPrice, OldPrice, AgentID, AgentCode);


                # endregion
            }
            catch (Exception ex)
            {
                _ = _exception.Error(ex);
                return dtPriceDetail;
            }

            return dtPriceDetail;
        }

        public async Task SaveCartPriceCheck(DataSet dsCartDetails, int j, int City, double UpdatedPrice, double OldPrice, string AgentID, string AgentCode)
        {
            try
            {
                string UserCartId = Convert.ToString(dsCartDetails.Tables[1].DefaultView[j]["UserCartId"]);
                string UserCartDetailId = Convert.ToString(dsCartDetails.Tables[1].DefaultView[j]["UserCartDetailId"]);
                string SupplierName = Convert.ToString(dsCartDetails.Tables[1].DefaultView[j]["SupplierName"]);
                string CityName = await GetCityNameSaveCartPriceCheck(City.ToString());
                string HotelName = Convert.ToString(dsCartDetails.Tables[1].DefaultView[j]["HotelName"]);
                string CheckInDate = Convert.ToString(dsCartDetails.Tables[1].DefaultView[j]["CheckInDate"]);
                CheckInDate = CheckInDate.Substring(6, 2) + "-" + CheckInDate.Substring(4, 2) + "-" + CheckInDate.Substring(0, 4);
                string CheckoOutDate = Convert.ToString(dsCartDetails.Tables[1].DefaultView[j]["CheckOutDate"]);
                CheckoOutDate = CheckoOutDate.Substring(6, 2) + "-" + CheckoOutDate.Substring(4, 2) + "-" + CheckoOutDate.Substring(0, 4);

                DataRow[] drroomcount = dsCartDetails.Tables[1].Select("UserCartId=" + UserCartId);
                int NoOfRoom = Convert.ToInt32(drroomcount.Count());


                bool IsCombine = Convert.ToBoolean(dsCartDetails.Tables[0].DefaultView[j]["IsCombineRoom"]);
                int NoOfAdult = 0;
                int NoOfChild = 0;

                if (IsCombine)
                {
                    int Adult = 0;
                    int Child = 0;
                    for (int x = 0; x < drroomcount.Length; x++)
                    {
                        int ADT = Convert.ToInt32(drroomcount[x]["NoOfAdults"]);
                        int CHD = Convert.ToInt32(drroomcount[x]["NoOfChild"]);

                        Adult = Adult + ADT;
                        Child = Child + CHD;

                    }
                    NoOfAdult = Adult;
                    NoOfChild = Child;
                }
                else
                {
                    NoOfAdult = Convert.ToInt32(dsCartDetails.Tables[1].DefaultView[j]["NoOfAdults"]);
                    NoOfChild = Convert.ToInt32(dsCartDetails.Tables[1].DefaultView[j]["NoOfChild"]);
                }

                string ErrorType = "";
                if (UpdatedPrice > 0)
                    ErrorType = "Price has been updated";
                else
                {
                    ErrorType = "Error at Price Check";
                }
                string RoomTypeID = Convert.ToString(dsCartDetails.Tables[1].DefaultView[j]["RoomTypeId"]);
                string XMLHotelId = Convert.ToString(dsCartDetails.Tables[1].DefaultView[j]["XMLHotelId"]);
                int RoomNumber = Convert.ToInt32(dsCartDetails.Tables[1].DefaultView[j]["RoomNumber"]);
                string XMLNationality = Convert.ToString(dsCartDetails.Tables[1].DefaultView[j]["XmlNationality"]);
                string Request = "";
                string Response = "";

                DataTable drRQRS = await GetThirdPartySaveCartPriceCheck(UserCartDetailId);

                if (drRQRS != null && drRQRS.Rows.Count > 0)
                {
                    Request = Convert.ToString(drRQRS.Rows[0]["XMLRequest"]);
                    Response = Convert.ToString(drRQRS.Rows[0]["XMLResponse"]);
                }
                await PostSvaCartPriceCheckData(UserCartId, UserCartDetailId, SupplierName, CityName, HotelName, CheckInDate, CheckoOutDate, NoOfRoom, NoOfAdult, NoOfChild, ErrorType, RoomTypeID, XMLHotelId, RoomNumber, XMLNationality, Request, Response, UpdatedPrice, OldPrice, AgentID, AgentCode);

            }
            catch (Exception ex)
            {
                _ = _exception.Error(ex);
            }
        }

