                }


                if (dsCartDetails != null && dsCartDetails.Tables.Count > 0)
                {
                    #region Validation
                    List<dsCartDetails_Table0> Table0 = HtmlExtensions.ToList<dsCartDetails_Table0>(dsCartDetails.Tables[0]);
                    List<dsCartDetails_Table1> Table1 = HtmlExtensions.ToList<dsCartDetails_Table1>(dsCartDetails.Tables[1]);
                    try
                    {
                        if (dsCartDetails.Tables[1] != null && dsCartDetails.Tables[1].Rows.Count > 0)
                        {
                            logdata.provider = Convert.ToString(dsCartDetails.Tables[1].Rows[0]["SupplierName"]);
                            bookResponse_1.DataforLog = logdata;

                        }
                    }
                    catch (Exception ex)
                    {

                    }
                    for (int i = 0; i < Table0.Count; i++)
                    {
                        List<dsCartDetails_Table1> list = Table1.Where(item => item.UserCartID == Table0[i].UserCartID).ToList();
                        if (list.Count > 0)
                        {
                            string[] AllNames = new string[bookRequest.BookRQ.HotelRooms.Count];
                            int allnamecount = 0;
                            for (int j = 0; j < list.Count; j++)
                            {
                                List<HotelRoomBookRQ> hotelRooms = bookRequest.BookRQ.HotelRooms.Where(item => (item.IsLead == 1 && item.PaxType.ToLower() == "adult")).ToList();
                                if (hotelRooms.Count == 0)
                                {
                                    //no lead
                                    bookResponse.Error.Add(GetErrorMsg(ErrorType.GeneralError, ErrorCode.RequestError, ErrorDescription.RequestError + "| No Lead Pax"));
                                    bookResponse_1.BookResponse = bookResponse;
                                    return bookResponse_1;
                                }
                                hotelRooms = bookRequest.BookRQ.HotelRooms.Where(item => (item.UniqueId == list[j].UserCartDetailId && item.RoomNo == list[j].RoomNumber)).ToList();
                                if (hotelRooms.Count > 0)
                                {
                                    #region Pax count validation //Due ticket ID#30880
                                    int Ad = 0;
                                    int Ch = 0;

                                    for (int n = 0; n < hotelRooms.Count; n++)
                                    {
                                        if (hotelRooms[n].PaxType == "Adult")
                                            Ad = Ad + 1;
                                        else
                                            Ch = Ch + 1;
                                    }

                                    if (Ad != list[j].NoOfAdults || Ch != list[j].NoOfChild)
                                    {
                                        bookResponse.Error.Add(GetErrorMsg(ErrorType.GeneralError, ErrorCode.RequestError, ErrorDescription.RequestError + "| Pax count not Matched"));
                                        bookResponse_1.BookResponse = bookResponse;
                                        return bookResponse_1;
                                    }
                                    #endregion
                                    if (hotelRooms.Count == (list[j].NoOfAdults + list[j].NoOfChild))
                                    {
                                        bool c1 = true;
                                        bool c2 = true;
                                        for (int k = 0; k < hotelRooms.Count; k++)
                                        {
                                            #region Child Age Compare between search & book RQ Ticket#15091
                                            if (hotelRooms[k].PaxType.ToLower() == "child")
                                            {
                                                if (list[j].ChildAge1 == Convert.ToInt32(hotelRooms[k].ChildAge) && c1)
                                                {
                                                    c1 = false;
                                                }
                                                else if (list[j].ChildAge2 == Convert.ToInt32(hotelRooms[k].ChildAge) && c2)
                                                {
                                                    c2 = false;
                                                }
                                                else
                                                {
                                                    bookResponse.Error.Add(GetErrorMsg(ErrorType.Mismatched, ErrorCode.Mismatched, ErrorDescription.RequestError + "| Child Age not matched with Search step."));
                                                    bookResponse_1.BookResponse = bookResponse;
                                                    return bookResponse_1;
                                                }
                                            }
                                            #endregion
                                            if (hotelRooms[k].FirstName == null ||
                                               hotelRooms[k].LastName == null ||
                                               hotelRooms[k].Prefix == null
                                               )
                                            {
                                                bookResponse.Error.Add(GetErrorMsg(ErrorType.GeneralError, ErrorCode.RequestError, ErrorDescription.RequestError + "| Check Request Parameters(FirstName,LastName,Prefix).."));
                                                bookResponse_1.BookResponse = bookResponse;
                                                return bookResponse_1;

                                            }

                                            if (hotelRooms[k].FirstName.Trim() == "" ||
                                                hotelRooms[k].LastName.Trim() == "" ||
                                                hotelRooms[k].Prefix.Trim() == "" ||
                                                 //hotelRooms[k].FirstName.Trim().Length > 25 || 
                                                 //hotelRooms[k].LastName.Trim().Length > 25 ||
                                                 hotelRooms[k].FirstName.Trim().Length > 100 || //Ticket #30030
                                                hotelRooms[k].LastName.Trim().Length > 100 ||
                                                hotelRooms[k].Prefix.Trim().Length > 4 ||
                                                 hotelRooms[k].FirstName.Trim().Length < 1 ||
                                                hotelRooms[k].LastName.Trim().Length < 1
                                                )
                                            {
                                                bookResponse.Error.Add(GetErrorMsg(ErrorType.GeneralError, ErrorCode.RequestError, ErrorDescription.RequestError + "| No blank name or invalid length "));
                                                bookResponse_1.BookResponse = bookResponse;
                                                return bookResponse_1;

                                            }

                                            #region Validation on Test keyword by Mustafa sir //Added on 19-FEB-2025
                                            string keyword = "test";
                                            string pattern = @"\b" + Regex.Escape(keyword) + @"\b"; // Ensures "test" is a whole word

                                            if (Regex.IsMatch(hotelRooms[k].FirstName?.Trim() ?? "", pattern, RegexOptions.IgnoreCase) ||
