        public static bool CheckPrefix(string prefix)//Added on 28-MAY-2024
        {
            bool Validation = true;
            switch (prefix.ToLower())
            {
                case "mr":
                case "mr.":
                case "ms":
                case "ms.":
                case "mrs":
                case "mrs.":
                    Validation = false;
                    break;
                default:
                    Validation = true;
                    break;
            }
            return Validation;
        }

        public bool CheckCreditAndDeposit(ref string BookingPaymentType, TokenData tokenData, int IsVouchered, DataSet dsprebook, ref bool IsPriceError, ref bool IsCreditLimitLow, string Searchkey = "")
        {
            string json = "";
            try
            {
                try
                {

                    try
                    {
                        json = JsonConvert.SerializeObject(dsprebook); ;
                    }
                    catch (Exception e)
                    {
                        json = e.Message;
                    }

                    _ = _exception.getException_v1("", "CheckCreditAndDeposit", "", "XMLOUT", Searchkey, json);
                }
                catch (Exception ex)
                {
                    _ = _exception.ErrorNew(ex, _LogAPI.Book, Searchkey, json);
                }
                //0 credit
                //1 card
                //type 2 - cash
                double TotalcartPrice = 0;
                DataTable dtMainAgentLimit = new DataTable();
                DataTable dtSubAgentLimit = new DataTable();
                bool IsBookingAllow = true;
                string PaymentType = "";




                if (IsVouchered == 1)
                {
                    TotalcartPrice = Convert.ToDouble(dsprebook.Tables[6].Rows[0]["TotalAmt"]);
                    dtMainAgentLimit = dsprebook.Tables[7];
                    if (TotalcartPrice <= 0 || dtMainAgentLimit.Rows.Count == 0)
                    {
                        IsBookingAllow = false;
                        IsPriceError = true;
                        return IsBookingAllow;
                    }
                    PaymentType = Convert.ToString(dsprebook.Tables[5].Rows[0]["AgentCreditType"]);
                    #region credit limit check New 
                    switch (PaymentType.ToLower())
                    {
                        case "credit":
                            {
                                // check main agent credit first 
                                decimal AgentAvailableLimit = (Convert.ToDecimal(Convert.ToString(dtMainAgentLimit.Rows[0][1])) - Convert.ToDecimal(dtMainAgentLimit.Rows[0]["UsedLimit"]));
                                decimal DepositAvailableLimit = Convert.ToDecimal(dtMainAgentLimit.Rows[0]["DepositLimit"]) - Convert.ToDecimal(dtMainAgentLimit.Rows[0]["UtilizeDepositLimit"]);
                                if (Convert.ToDecimal(Math.Round(Convert.ToDecimal(Convert.ToDecimal(TotalcartPrice)), 2)) > Convert.ToDecimal(AgentAvailableLimit))
                                {
                                    BookingPaymentType = "15";
                                    //if (Convert.ToDecimal(Math.Round(Convert.ToDecimal(Convert.ToDecimal(TotalcartPrice)), 2)) > Convert.ToDecimal(DepositAvailableLimit))
                                    //{
                                    //    IsBookingAllow = false;
                                    //    return IsBookingAllow;
                                    //}
                                    IsBookingAllow = false;
                                    IsCreditLimitLow = true;
                                    return IsBookingAllow;
                                }

                            }

                            break;
                        case "cash":
                            {
                                BookingPaymentType = "15";
                                decimal DepositeAvailableLimit = Convert.ToDecimal(Convert.ToString(dtMainAgentLimit.Rows[0]["DepositLimit"])) - Convert.ToDecimal(Convert.ToString(dtMainAgentLimit.Rows[0]["UtilizeDepositLimit"]));
                                if (Convert.ToDecimal(Math.Round(Convert.ToDecimal(Convert.ToDecimal(TotalcartPrice)), 2)) > Convert.ToDecimal(DepositeAvailableLimit))
                                {
                                    IsBookingAllow = false;
                                    IsCreditLimitLow = true;
                                    return IsBookingAllow;
                                }

                            }
                            break;

                        default:
                            IsBookingAllow = false;
                            return IsBookingAllow;
                            break;
                    }
                    if (tokenData.Type.ToLower() == "subagent")
                    {
                        try
                        {
                            dtSubAgentLimit = dsprebook.Tables[3];
                            if (TotalcartPrice <= 0 || dtSubAgentLimit.Rows.Count == 0)
                            {
                                IsBookingAllow = false;
                                return IsBookingAllow;
                            }
                            {
                                decimal subAgentAvailableLimit = (Convert.ToDecimal(Convert.ToString(dtSubAgentLimit.Rows[0][1])) - Convert.ToDecimal(dtSubAgentLimit.Rows[0]["UsedLimit"]));
                                decimal subDepositAvailableLimit = (Convert.ToDecimal(dtSubAgentLimit.Rows[0]["DepositLimit"]) - Convert.ToDecimal(dtSubAgentLimit.Rows[0]["UtilizeDepositLimit"]));

                                if (Convert.ToDecimal(Math.Round(Convert.ToDecimal(Convert.ToDecimal(TotalcartPrice)), 2)) > Convert.ToDecimal(subAgentAvailableLimit))
                                {
                                    BookingPaymentType = "2";
                                    if (Convert.ToDecimal(Math.Round(Convert.ToDecimal(Convert.ToDecimal(TotalcartPrice)), 2)) > Convert.ToDecimal(subDepositAvailableLimit))
                                    {
                                        IsBookingAllow = false;
                                        IsCreditLimitLow = true;
                                        return IsBookingAllow;
                                    }
                                }
                                //}
                            }

                        }
                        catch (Exception ex)
                        {
                            _ = _exception.ErrorNew(ex, _LogAPI.Book, Searchkey, json);
                        }
                    }
                    #endregion
                }
                return IsBookingAllow;
            }
            catch (Exception ex)
            {
                _ = _exception.ErrorNew(ex, _LogAPI.Book, Searchkey, json);
                return false;
            }
        }

