        #region Gimmonix

        public async Task GimmonixProcess(string AgentUniqueNo, int i, DataSet dsCartDetails, string referenceNumber, int cartId, DataTable dtpassengersweb, DataTable dtTourCancellationweb, DataTable dtAgentVoucher, DataTable dtHotelAllocation, DataTable DtHotelRateBreakeUpweb, TokenData tokenData, DataTable dtCheckPriceReqStructure = null)
        {
            string RequestString = "";
            try
            {
                string RequestGimmonix = "", RT_Responsedata = "";
                int IsCombineRoom = Convert.ToInt32(dsCartDetails.Tables[0].Rows[i]["IsCombineRoom"]);
                if (IsCombineRoom == 1)
                {
                    string UniqueNo1 = Convert.ToString(dsCartDetails.Tables[1].DefaultView[0]["UserCartDetailId"]);


                    RequestGimmonix = await GetDataForGimmonix(IsCombineRoom, i, 0, dsCartDetails, referenceNumber, cartId, dtpassengersweb, dtTourCancellationweb, dtAgentVoucher, dtHotelAllocation, DtHotelRateBreakeUpweb, tokenData, dtCheckPriceReqStructure);
                    _commonMethod.ThirdPartyBookingHistory(Convert.ToString(UniqueNo1), Convert.ToString(AgentUniqueNo), RequestGimmonix, "-", "Before Request hit booking", Convert.ToString("Ratefox"), "Response Error", referenceNumber, "WithinEarth");

                    if (RequestGimmonix != "")
                    {
                        RT_Responsedata = await GetResponseGimmonix(RequestGimmonix, 20000);
                        _commonMethod.ThirdPartyBookingHistory(Convert.ToString(UniqueNo1), Convert.ToString(AgentUniqueNo), RequestGimmonix, RT_Responsedata, "After Request hit booking", Convert.ToString("Ratefox"), "Response Error", referenceNumber, "WithinEarth");

                    }
                }
                else
                {
                    for (int rt = 0; rt < dsCartDetails.Tables[1].DefaultView.Count; rt++)
                    {
                        string UniqueNo12 = Convert.ToString(dsCartDetails.Tables[1].DefaultView[rt]["UserCartDetailId"]);


                        RequestGimmonix = await GetDataForGimmonix(IsCombineRoom, i, rt, dsCartDetails, referenceNumber, cartId, dtpassengersweb, dtTourCancellationweb, dtAgentVoucher, dtHotelAllocation, DtHotelRateBreakeUpweb, tokenData, dtCheckPriceReqStructure);
                        _commonMethod.ThirdPartyBookingHistory(Convert.ToString(UniqueNo12), Convert.ToString(AgentUniqueNo), RequestGimmonix, "-", "Before Request hit booking", Convert.ToString("Ratefox"), "Response Error", referenceNumber, "WithinEarth");

                        if (RequestGimmonix != "")
                        {
                            RT_Responsedata = await GetResponseGimmonix(RequestGimmonix, 20000);
                            _commonMethod.ThirdPartyBookingHistory(Convert.ToString(UniqueNo12), Convert.ToString(AgentUniqueNo), RequestGimmonix, RT_Responsedata, "After Request hit booking", Convert.ToString("Ratefox"), "Response Error", referenceNumber, "WithinEarth");

                        }
                    }
                }
            }
            catch (Exception ex)
            {
                _ = _exception.ErrorBooking(ex, "");
                //return RequestString + ex.ToString();
            }
            //return RequestString;
        }
        public async Task<string> GetDataForGimmonix(int IsCombineRoom, int i, int rt, DataSet dsCartDetails, string Referenceno, int cartId, DataTable dtPassengers, DataTable dtTourCancellation, DataTable dtAgentVoucher, DataTable dtHotelAllocation, DataTable DtHotelRateBreakeUp, TokenData tokenData, DataTable dtCheckPriceReq = null)
        {
            string RequestString = "";
            string UniqueNoumber = "";
            try
            {
                int supplierid = 0;

                {
                    // for (int i = 0; i < dsCartDetails.Tables[1].DefaultView.Count; i++)
                    {
                        supplierid = await _commonMethod.GetSupplierforgimmonix(Convert.ToString(dsCartDetails.Tables[1].DefaultView[rt]["SupplierName"]));
                        if (supplierid > 0)
                        {


                            string CheckIn = Convert.ToString(dsCartDetails.Tables[0].Rows[i]["CheckInDate"]);//"20180327"
                            CheckIn = CheckIn.Substring(0, 4) + "-" + CheckIn.Substring(4, 2) + "-" + CheckIn.Substring(6, 2);
                            string CheckOut = Convert.ToString(dsCartDetails.Tables[0].Rows[i]["CheckOutDate"]);
                            CheckOut = CheckOut.Substring(0, 4) + "-" + CheckOut.Substring(4, 2) + "-" + CheckOut.Substring(6, 2);

                            string UniqueNo = Convert.ToString(dsCartDetails.Tables[1].DefaultView[rt]["UserCartDetailId"]);


                            JsonSerializerSettings Setting = new JsonSerializerSettings();
                            Gimmonix.Root Settings = new Gimmonix.Root();
                            Gimmonix.SupplierHotel SupplierDetail = new Gimmonix.SupplierHotel();
                            SupplierDetail.SupplierId = supplierid;// 1165;// Convert.ToInt32(dsCartDetails.Tables[0].Rows[rt]["SupplierId"]);
                            SupplierDetail.SupplierHotelId = Convert.ToString(dsCartDetails.Tables[0].Rows[i]["XMLHotelId"]);
                            Settings.SupplierHotel = SupplierDetail;
                            Settings.CheckIn = Convert.ToDateTime(CheckIn);
                            Settings.CheckOut = Convert.ToDateTime(CheckOut);
                            Settings.Residency = Convert.ToString(dsCartDetails.Tables[1].DefaultView[rt]["XmlNationality"]);
                            Gimmonix.Price Prices = new Gimmonix.Price();
                            //Prices.BookingPrice = Convert.ToDouble(dsCartDetails.Tables[1].DefaultView[rt]["CompanyBuyingPrice"]);
                            Prices.Currency = "USD";// Convert.ToString(dsCartDetails.Tables[0].Rows[i]["SupplierCurrency"]);
                            string Suppliername = Convert.ToString(dsCartDetails.Tables[1].DefaultView[rt]["SupplierName"]);

                            string Currency = "USD";// Convert.ToString(dsCartDetails.Tables[0].Rows[i]["SupplierCurrency"]); //Static Currency Added USD 16-june-2025 
                            double CurrencyFactor = 1;
                            if (Currency.ToLower() != tokenData.SiteCurrency.ToLower())
                            {
                                //DataTable dtInrCurrency = Common.GetCountryCurrency(Convert.ToString(dsCartDetails.Tables[0].Rows[i]["SupplierCurrency"]));
                                //CurrencyFactor = Convert.ToDouble(dtInrCurrency.Rows[0]["AmtToExch"]);

                                CurrencyFactor = _commonMethod.GetROEByCurrency(Convert.ToString(dsCartDetails.Tables[0].Rows[i]["SupplierCurrency"]), tokenData.dtROE);
                            }

                            if (Suppliername.ToLower().Contains("ean"))
                            {
                                Prices.BookingPrice = Convert.ToDouble(dsCartDetails.Tables[1].DefaultView[rt]["EachoToken"]) * CurrencyFactor;
                            }
                            else
                            {
                                Prices.BookingPrice = Convert.ToDouble(dsCartDetails.Tables[1].DefaultView[rt]["CompanyBuyingPrice"]) * CurrencyFactor;
                            }

                            Gimmonix.TotalTax Tax = new Gimmonix.TotalTax();
                            Tax.Amount = 0;
                            Tax.IsIncluded = true;
