        public async Task<string> GetResponseGimmonix(string Request, int TimeOut)
        {
            string Responsedata = "";
            string UserName = "ratefox_ev@withinearth";
            string Password = "tGF!8Ik";
            string Url = "https://api.ratefox.io/hotels/ratefox";
            System.Diagnostics.Stopwatch timer = new System.Diagnostics.Stopwatch();
            timer.Start();
            ServicePointManager.Expect100Continue = true;
            ServicePointManager.SecurityProtocol = SecurityProtocolType.Tls
                   | SecurityProtocolType.Tls11
                   | SecurityProtocolType.Tls12
                   | SecurityProtocolType.Ssl3;
            HttpWebRequest httpWebRequest = null;
            HttpWebResponse httpWebResponse = null;
            try
            {
                string Key = Convert.ToBase64String(Encoding.ASCII.GetBytes(UserName + ":" + Password));
                httpWebRequest = (HttpWebRequest)WebRequest.Create(Url);
                byte[] bytes;
                bytes = System.Text.Encoding.UTF8.GetBytes(Request);
                //Set HttpWebRequest properties
                httpWebRequest.Method = "POST";
                httpWebRequest.Timeout = 25000;
                httpWebRequest.ContentLength = bytes.Length;
                httpWebRequest.Method = "POST";
                httpWebRequest.ContentType = "application/json";
                // httpWebRequest.Headers.Add("Accept-Encoding", "gzip, deflate");
                httpWebRequest.Headers.Add("Authorization", "Basic " + Key);

                using (Stream requestStream = httpWebRequest.GetRequestStream())
                {
                    //Writes a sequence of bytes to the current stream                     
                    requestStream.Write(bytes, 0, bytes.Length);
                    requestStream.Close();//Close stream
                }
                //Sends the HttpWebRequest, and waits for a response.
                httpWebResponse = (HttpWebResponse)await httpWebRequest.GetResponseAsync();
                if (httpWebResponse.StatusCode == HttpStatusCode.OK)
                {
                    //Get response stream into StreamReader 
                    using (Stream responseStream = httpWebResponse.GetResponseStream())
                    {
                        using (StreamReader reader = new StreamReader(responseStream))
                            Responsedata = await reader.ReadToEndAsync();
                    }
                    timer.Stop();
                }
            }
            catch (Exception ex)
            {
                _ = _exception.ErrorBooking(ex, "");
                return ex.Message.ToString();
            }
            return Responsedata;
        }

