        public static DataRow AddBookingDataRow(DataRow newRow, string UserCartId, string UserCartDetailId, string AgentVoucherNo, string XMLRequest, string XMLResponse, string SupplierName, int bookingStatus, int Packageid = 0, string EssentialInfo = "")
