        public async Task<BookingDetailResponse_newapi> BookingDetail(BookingDetailRequest bookingDetailRequest, TokenData TokenData, AdvancedOptions advancedOptions, string JsonRQ, string userAgent, string IP, string HostName)
        {
            BookingDetailResponse_newapi bookingDetailResponse_newapi = new BookingDetailResponse_newapi();
            BookingDetailResponse bookingDetailResponse = new BookingDetailResponse();
            DataforLogBD logdata = new DataforLogBD();

            try
            {
                string IdToSearch = "";
                Int64 bookingId = bookingDetailRequest.BookingDetailRQ.BookingId;
                string Internalref = bookingDetailRequest.BookingDetailRQ.InternalReference;
                Internalref = Internalref == null ? "" : Internalref;
                string ReferenceNo = bookingDetailRequest.BookingDetailRQ.ReferenceNo == null ? "" : bookingDetailRequest.BookingDetailRQ.ReferenceNo;

                string SearchBy = GetSearchBy(Internalref, bookingId);

                if (SearchBy == SearchBookingBy.byreference && ReferenceNo == "")
                {
                    bookingDetailResponse.Error.Add(GetErrorMsg(ErrorType.RequestError, ErrorCode.RequestError, ErrorDescription.RequestError));
                    bookingDetailResponse_newapi.BookingDetailResponse = bookingDetailResponse;
                    return bookingDetailResponse_newapi;
                }

                DataSet dataSet = await _commonMethod.GetShoppingCartTravelCart(ReferenceNo, bookingId, Internalref, SearchBy, TokenData.AgentId);

                if (dataSet != null && dataSet.Tables.Count > 0 && dataSet.Tables[0].Rows.Count > 0)
                {
                    //@New
                    try
                    {
                        logdata.Ref = Convert.ToString(dataSet.Tables[0].Rows[0]["ReferenceNo"]);
                        logdata.IntRef = Convert.ToString(dataSet.Tables[0].Rows[0]["APIInternalReference"]);
                    }
                    catch (Exception ex)
                    {
                        _ = _exception.Error(ex);
                    }
                    // -----
                    XConnect.Models.BookingDetailRS bookingDetailRS = new XConnect.Models.BookingDetailRS();
                    HotelOption_Detail hotelOption_Detail = new HotelOption_Detail();
                    hotelOption_Detail.BookingId = Convert.ToInt64(dataSet.Tables[0].Rows[0]["BookingId"]);
                    hotelOption_Detail.ReferenceNo = Convert.ToString(dataSet.Tables[0].Rows[0]["ReferenceNo"]);

                    hotelOption_Detail.CheckInDate = Convert.ToString(Convert.ToDateTime(dataSet.Tables[0].Rows[0]["TravelDate"]).ToString("MM-dd-yyyy"));
                    hotelOption_Detail.CheckOutDate = Convert.ToString(Convert.ToDateTime(dataSet.Tables[0].Rows[0]["CheckOutDate"]).ToString("MM-dd-yyyy"));
                    hotelOption_Detail.BookingDate = Convert.ToString(Convert.ToDateTime(dataSet.Tables[0].Rows[0]["BookingDate"]).ToString("MM-dd-yyyy"));
                    //hotelOption_Detail.DeadLineDate = Convert.ToString(dataSet.Tables[0].Rows[0]["CheckOutDate"]);
                    //hotelOption_Detail.Currency = Convert.ToString((dataSet.Tables[0].Rows[0]["CurrencyId"]));

                    hotelOption_Detail.HotelId = Convert.ToString(dataSet.Tables[0].Rows[0]["RaynaId"]);
                    hotelOption_Detail.HotelName = Convert.ToString(dataSet.Tables[0].Rows[0]["TourName"]);
                    hotelOption_Detail.LeadPaxName = Convert.ToString(dataSet.Tables[0].Rows[0]["Name"]);
                    try
                    {
                        logdata.hotelid = Convert.ToInt64(hotelOption_Detail.HotelId);
                        logdata.hotelname = hotelOption_Detail.HotelName;
                        logdata.provider = Convert.ToString(dataSet.Tables[0].Rows[0]["Provider"]);
                    }
                    catch (Exception ex)
                    {
                        _ = _exception.Error(ex);
                    }
                    List<HotelRoom_Detail> hotelRoomDetails = new List<HotelRoom_Detail>();
                    decimal TotalPrice = 0;
                    for (int i = 0; i < dataSet.Tables[0].Rows.Count; i++)
                    {
                        string SupplierCurrency = Convert.ToString(dataSet.Tables[0].Rows[i]["SupplierCurrencyCode"]);
                        HotelRoom_Detail hotelRoom = new HotelRoom_Detail();
                        hotelRoom.MealName = Convert.ToString(dataSet.Tables[0].Rows[i]["Board"]);
                        hotelRoom.MappedMealName = Convert.ToString(dataSet.Tables[0].Rows[i]["MappedMealName"]);

                        hotelRoom.BookingStatus = Convert.ToString(dataSet.Tables[0].Rows[i]["BookingStatus"]);
                        hotelRoom.Price = Convert.ToDecimal(dataSet.Tables[0].Rows[i]["TotalAmount"]);

                        TotalPrice = TotalPrice + hotelRoom.Price;
                        decimal CancellationAmount = Convert.ToDecimal(dataSet.Tables[0].Rows[i]["CancellationAmount"]);
                        if (hotelRoom.BookingStatus.ToLower() == "Cancelled".ToLower() || hotelRoom.BookingStatus.ToLower() == "Cancel Charge".ToLower())
                        {
                            TotalPrice = TotalPrice + CancellationAmount - hotelRoom.Price;
                            hotelRoom.Price = CancellationAmount;
                        }
                        //TotalPrice += hotelRoom.Price;
                        hotelRoom.RoomNo = Convert.ToString(dataSet.Tables[0].Rows[i]["indexsrno"]);
                        hotelRoom.RoomTypeName = Convert.ToString(dataSet.Tables[0].Rows[i]["RoomType"]);
                        Int64 DetailId = Convert.ToInt64(dataSet.Tables[0].Rows[i]["Id"]);
                        Int64 MasterID = Convert.ToInt64(dataSet.Tables[0].Rows[i]["BookingId"]);

                        List<CancellationPolicy_Detail> CancellationPolicyList = new List<CancellationPolicy_Detail>();

                        if (hotelRoom.BookingStatus.ToLower() != "Cancelled".ToLower()
                            && hotelRoom.BookingStatus.ToLower() != "Cancel Charge"
                            && hotelRoom.BookingStatus.ToLower() != "Completed".ToLower()
                            && hotelRoom.BookingStatus.ToLower() != "Not Confirmed".ToLower())
                        {
                            DataRow[] drPolicy = dataSet.Tables[2].Select("Id=" + DetailId + " and BookingId=" + MasterID);
                            for (int j = 0; j < drPolicy.Length; j++)
                            {
                                CancellationPolicy_Detail policy_Detail = new CancellationPolicy_Detail();
                                policy_Detail.FromDate = Convert.ToDateTime(drPolicy[j]["FromDate"]).ToString("MM-dd-yyyy");
                                policy_Detail.ToDate = Convert.ToDateTime(drPolicy[j]["ToDate"]).ToString("MM-dd-yyyy");
                                policy_Detail.CancellationPrice = Convert.ToDecimal(drPolicy[j]["CancellationAmount"]);
                                // policy_Detail.CancellationPrice = policy_Detail.CancellationPrice.CalculatePrice(TokenData, advancedOptions, SupplierCurrency);
                                CancellationPolicyList.Add(policy_Detail);
                            }
                        }
                        hotelRoom.CancellationPolicy = CancellationPolicyList;


                        List<Passenger_Detail> PassengerList = new List<Passenger_Detail>();
                        DataRow[] drPaxes = dataSet.Tables[1].Select("Id=" + DetailId + " and BookingId=" + MasterID);

                        for (int j = 0; j < drPaxes.Length; j++)
                        {
                            Passenger_Detail passenger = new Passenger_Detail();
                            passenger.ChildAge = Convert.ToString(drPaxes[j]["ChildAge"]);
                            passenger.Name = Convert.ToString(drPaxes[j]["Name"]);
                            passenger.IsLead = Convert.ToInt32(drPaxes[j]["IsLead"]);
                            passenger.PaxType = Convert.ToString(drPaxes[j]["passangertype"]);
                            PassengerList.Add(passenger);
                        }
                        hotelRoom.Passenger = PassengerList;
                        hotelRoomDetails.Add(hotelRoom);
                    }

                    hotelOption_Detail.HotelRooms = hotelRoomDetails;
                    hotelOption_Detail.InternalReference = Convert.ToString(dataSet.Tables[0].Rows[0]["APIInternalReference"]);
                    hotelOption_Detail.Nationality = Convert.ToString(dataSet.Tables[0].Rows[0]["Country"]);
                    //hotelOption_Detail.Status = "";
                    hotelOption_Detail.TotalPrice = TotalPrice;


                    bookingDetailRS.HotelOption = hotelOption_Detail;

                    bookingDetailResponse.BookingDetailRS = bookingDetailRS;

                    bookingDetailResponse_newapi.BookingDetailResponse = bookingDetailResponse;
                    bookingDetailResponse_newapi.DataforLogBD = logdata;
                }
                else
                {
                    bookingDetailResponse.Error.Add(GetErrorMsg(ErrorType.GeneralError, ErrorCode.NorecordError, ErrorDescription.NorecordError));
                    bookingDetailResponse_newapi.BookingDetailResponse = bookingDetailResponse;
                }
                return bookingDetailResponse_newapi;
            }
            catch (Exception ex)
            {
                _ = _exception.Error(ex);
                return null;
            }
        }


        public string GetSearchBy(string Internalref, Int64 bookingId)
        {
            try
            {
                string SearchBy = "";

                if (!string.IsNullOrEmpty(Internalref))
                {
                    SearchBy = SearchBookingBy.byInternal;
                    // IdToSearch = Internalref;
                }
                else
                {
                    if (bookingId != 0)
                    {
                        SearchBy = SearchBookingBy.byBookingid;
                        // IdToSearch = Convert.ToString(bookingId);
                    }
                    else
                    {
                        SearchBy = SearchBookingBy.byreference;
                        // IdToSearch = ReferenceNo;
                    }

                }
                return SearchBy;
            }
            catch (Exception ex)
            {
                _ = _exception.Error(ex);
                return "";
            }
        }
