        #region Cancel Booking
        public static string SeperatorRow = "[~]";
        public static string SeperateID = "|7^|";

        public async Task<CheckChargesResponse> CheckHotelCancellationCharges(CheckChargesRequest checkChargesRequest, TokenData tokenData, AdvancedOptions advancedOptions)
        {
            CheckChargesResponse checkChargesResponse = new CheckChargesResponse();
            try
            {
                CheckHotelCancellationChargesRQ RQ = checkChargesRequest.CheckHotelCancellationChargesRQ;

                string SearchBy = GetSearchBy(RQ.InternalReference, RQ.BookingId);
                if (SearchBy == SearchBookingBy.byreference && RQ.ReferenceNo == "")
                {
                    checkChargesResponse.Error.Add(GetErrorMsg(ErrorType.RequestError, ErrorCode.RequestError, ErrorCode.RequestError));
                    return checkChargesResponse;
                }
                DataTable dt = await _commonMethod.GetCheckHotelCancellationCharges(tokenData.AgentId, RQ.BookingId, SearchBy, RQ.ReferenceNo, RQ.InternalReference);
                if (dt != null && dt.Rows.Count > 0)
                {
                    HotelOption_Policy HotelOption = new HotelOption_Policy();
                    List<HotelRoom_Policy> list = new List<HotelRoom_Policy>();
                    string token = "";
                    decimal TotalCharge = 0;
                    decimal TotalPrice = 0;
                    decimal TotalRefund = 0;
                    bool NotAllow = false;
                    for (int i = 0; i < dt.Rows.Count; i++)
                    {
                        string DetailId = Convert.ToString(dt.Rows[i]["BookingDetailsId"]);
                        string status = Convert.ToString(dt.Rows[i]["BookingStatus"]);
                        string SupplierCurrency = Convert.ToString(dt.Rows[i]["SupplierCurrency"]);

                        if (status == "" || status == "2" || status == "3" || status == "1")
                            continue;
                        HotelRoom_Policy policy = new HotelRoom_Policy();
                        policy.BookingDetailId = Convert.ToInt64(DetailId);
                        policy.Price = Convert.ToDecimal(dt.Rows[i]["BookingAmount"]).CalculatePrice(tokenData, advancedOptions, SupplierCurrency);
                        policy.RefundAmount = Convert.ToDecimal(dt.Rows[i]["RefundableAmount"]).CalculatePrice(tokenData, advancedOptions, SupplierCurrency);
                        policy.RoomTypeName = Convert.ToString(dt.Rows[i]["RoomType"]);

                        list.Add(policy);

                        TotalCharge += (policy.Price - policy.RefundAmount);
                        TotalPrice += policy.Price;
                        TotalRefund += policy.RefundAmount;
                        #region "Token"
                        List<string> policytoken = new List<string>();
                        policytoken.Add(DetailId);
                        policytoken.Add(policy.RefundAmount.ToString());
                        policytoken.Add(HotelXML.SeperatorRow);
                        token += string.Join(HotelXML.SeperateID, policytoken.ToArray());
                        #endregion
                    }

                    HotelOption.HotelRooms = list;
                    HotelOption.TotalCharge = TotalCharge;
                    HotelOption.TotalPrice = TotalPrice;
                    HotelOption.TotalRefund = TotalRefund;
                    HotelOption.BookingId = Convert.ToInt64(dt.Rows[0]["OnlineBookingMasterId"]);
                    HotelOption.CancelCode = token.ToBase64StringManual(true);

                    CheckHotelCancellationChargesRS RS = new CheckHotelCancellationChargesRS();
                    RS.HotelOption = HotelOption;
                    if (NotAllow)
                        checkChargesResponse.Error.Add(GetErrorMsg(ErrorType.NoPermission, ErrorCode.NoPermission, ErrorDescription.NoPermission_Cancel));
                    else
                        checkChargesResponse.CheckHotelCancellationChargesRS = RS;
                }
                else
                    checkChargesResponse.Error.Add(GetErrorMsg(ErrorType.GeneralError, ErrorCode.NorecordError, ErrorDescription.NorecordError));


                return checkChargesResponse;
            }
            catch (Exception ex)
            {
                _ = _exception.ErrorNew(ex, _LogAPI.CancelBooking);
                return null;
            }
        }

