        public async Task<BookResponse> ReBookPruvoMarketPlace(Class_Pruvo.ReBook_PruvoMarketPlace bookRequest, TokenData tokenData, AdvancedOptions advancedOptions, string IP)
        {

            BookResponse bookResponse = new BookResponse();
            BookRS Book_RS = new BookRS();
            try
            {
                string ip = IP;
                int GuestUserID = Convert.ToInt32(await _commonMethod.GetUserCartId(tokenData.AgentId));
                SqlParameter[] para = new SqlParameter[]{
                new SqlParameter("@AgentId",tokenData.AgentId),
                new SqlParameter("@OldBookingId",bookRequest.OldBookingId),
                new SqlParameter("@OldBookingDetailID",bookRequest.OldBookingDetailID),
                new SqlParameter("@Price",bookRequest.newPrice),
                new SqlParameter("@GuestUserId",GuestUserID),
                new SqlParameter("@IP",ip),
                new SqlParameter("@SupplierName","Pruvo_MarketPlace"),
                new SqlParameter("@APIInternalReference",bookRequest.InternalReference),
                new SqlParameter("@AgentVoucherNo",bookRequest.pruvoItinerary),
                new SqlParameter("@MasterSupplierId",825),
                new SqlParameter("@pruvoUserid",bookRequest.pruvoUserid),
                };
                DataTable dt = (await _dlConnection.GetDataTableAsync("SaveCartDataFor_PruvoMarketPlace", para, 120));
                Book_RS.BookingId = Convert.ToInt64(dt.Rows[0]["BookingId"]);
                Book_RS.ReferenceNo = Convert.ToString(dt.Rows[0]["ReferenceNo"]);
                Book_RS.InternalReference = Convert.ToString(dt.Rows[0]["InternalReference"]);
                Book_RS.Currency = tokenData.CreditLimitCurrencyName;
                bookResponse.BookRS = Book_RS;



            }
            catch (Exception X)
            {
                _ = _exception.ErrorBooking(X, tokenData.AgentId.ToString(), bookRequest.InternalReference, Convert.ToString(bookRequest.OldBookingDetailID));
            }

            return bookResponse;
        }
