        public async Task<bool> GetRedisCache_oth(CacheSearchpara SearchPara, string HotelID, string checkInDate, string checkOutDate, int CityID)
        {
            string CacheKey_log = "";
            try
            {
                CancellationTokenSource cts = new CancellationTokenSource(TimeSpan.FromSeconds(2000));
                DataTable dttempRoomTable = new DataTable();
                dttempRoomTable.Columns.Add("RoomNo");
                dttempRoomTable.Columns.Add("NoOfAdult");
                dttempRoomTable.Columns.Add("NoOfChild");
                dttempRoomTable.Columns.Add("ChildAge1");
                dttempRoomTable.Columns.Add("ChildAge2");
                string IncludeOnRequest = "N";

                for (int r = 0; r < 1; r++)
                {
                    DataRow dr = dttempRoomTable.NewRow();
                    dr["RoomNo"] = r + 1;
                    dr["NoOfAdult"] = SearchPara.NoofAdults;
                    dr["NoOfChild"] = SearchPara.NoOfChild;
                    dr["ChildAge1"] = SearchPara.ChildAge1;
                    dr["ChildAge2"] = SearchPara.ChildAge2;
                    dttempRoomTable.Rows.Add(dr);
                }
                DataSet ds = new DataSet();
                System.Diagnostics.Stopwatch timerroomprocess11x = new System.Diagnostics.Stopwatch();
                timerroomprocess11x.Start();

                SqlParameter[] para = new SqlParameter[] {
                   new SqlParameter("@CityId", CityID),
                   new SqlParameter("@CheckInDate", checkInDate.Substring(0,2)+"/"+checkInDate.Substring(3,2)+"/"+checkInDate.Substring(6,4)),
                   new SqlParameter("@CheckOutDate", checkOutDate.Substring(0,2)+"/"+checkOutDate.Substring(3,2)+"/"+checkOutDate.Substring(6,4)),
                   new SqlParameter("@RatingStartEnd", Convert.ToInt32(1)),
                   new SqlParameter("@RatingEnd", Convert.ToInt32(5)),
                   new SqlParameter("@tempRoomTableNEW", dttempRoomTable),
                   new SqlParameter("@PassangerNatinality", SearchPara.Nationality),
                   new SqlParameter("@AgentId", 2172),
                   new SqlParameter("@HotelId", ""), // or remove if unused
                   new SqlParameter("@IsAvailable", IncludeOnRequest == "N" ? 1 : 0),
                   new SqlParameter("@HotelIDs", HotelID),
                   new SqlParameter("@CompanyId", 1),
                   new SqlParameter("@dno", 0)
                                                                            };

                ds = await _dlConnection.GetDataSetAsync_Limit_OTHDB_2_Redis("GetOwnInventoryHotelRate_B2B_Agent_V12_XConnect_New_2024_optimize_Live", para, cts.Token, 2).ConfigureAwait(false);
                timerroomprocess11x.Stop();
                timerroomprocess11x.Elapsed.ToString();
                //if (timerroomprocess11x.ElapsedMilliseconds > 4000)
                {
                    //Log_Time($"ResException {"SPTime :" + timerroomprocess11x.Elapsed.ToString()}", "SP_TimerLog.txt");
                }
                //if (ds != null && ds.Tables.Count > 1 && ds.Tables[0].Rows.Count > 0)//Comment on 5-SEP-2025
                if (ds != null && ds.Tables.Count > 1)
                {
                    try
                    {
                        string json = Newtonsoft.Json.JsonConvert.SerializeObject(ds, Newtonsoft.Json.Formatting.Indented);
                        string CacheKey = CreateRadisCacheKey(HotelID, SearchPara, checkInDate, checkOutDate, SearchPara.nights);
                        CacheKey_log = CacheKey;
                        if (_redis == null || !_redis.IsConnected)
                            _redis = await ConnectionMultiplexer.ConnectAsync("10.32.8.205:6379");

                        IDatabase db = _redis.GetDatabase(0);

                        TimeSpan expiry = TimeSpan.FromHours(SearchPara.RefreshCacheHour);
                        System.Diagnostics.Stopwatch RediaTime = new System.Diagnostics.Stopwatch();
                        RediaTime.Start();
                        await db.StringSetAsync(CacheKey, json, expiry);
                        RediaTime.Stop();
                        //timerroomprocess11x.Elapsed.ToString();
                        if (RediaTime.ElapsedMilliseconds > 2000)
                        {
                            await _exception.getException_v2(RediaTime.Elapsed.ToString(), "RedisTime>2000", "", "");
                        }
                    }
                    catch (Exception ex)
                    {
                        await _exception.getException_v2(ex.Message, "RedisError", "", "", CacheKey_log);
                        return false;
                    }
                }

                return true;

            }
            catch (Exception x)
            {
                await _exception.getException_v2(x.Message, "OTH SP Error", "", "", CacheKey_log);
                return false;
            }
        }

        public static string CreateRadisCacheKey(string HotelId, CacheSearchpara SearchPara, string CheckInDate, string CheckOutDate, int NoofNights)//Added on 27-MAY-2025
        {
            try
            {
                StringBuilder RoomDataKeyBuilder = new StringBuilder();
                //for (int r = 0; r < SearchPara.Rooms.Count; r++)
                for (int r = 0; r < 1; r++)
                {
                    int roomNumber = r + 1;
                    RoomDataKeyBuilder.Append($"R{roomNumber}A={SearchPara.NoofAdults}+");
                    RoomDataKeyBuilder.Append($"R{roomNumber}C1A={ChildAgeGrouping(SearchPara.ChildAge1)}+");
                    RoomDataKeyBuilder.Append($"R{roomNumber}C2A={ChildAgeGrouping(SearchPara.ChildAge2)}+");
                }
                // Remove trailing '+'
                if (RoomDataKeyBuilder.Length > 0)
                {
                    RoomDataKeyBuilder.Length--; // remove last '+'
                }

                string RoomDataKey = RoomDataKeyBuilder.ToString();

                string CacheKey = "OTH_Hid#" + HotelId + "_CI#" + CheckInDate + "_CO#" + CheckOutDate + "_NN#" + NoofNights + "_RD#" + RoomDataKey + "_NA#" + SearchPara.Nationality + "";
                return CacheKey;
            }
            catch (Exception x)
            {
                //_exception.Error(x);
                return "";
            }
        }

